INSERT INTO `questions` VALUES (1,'math_addition','maths','What is 8 + 3 = _______','What is eight plus three?','en','multiple_choice','images/maths/8_plus_3.jpg',NULL,'[\"9\",\"10\",\"11\",\"12\"]','11','Keep 8 in your mind, put up 3 fingers, and count forward!','Keep 8 in your mind, put up 3 fingers, and count forward!',NULL,0,'Kindergarten 3 (KG3)'),(2,'math_addition','maths','What is 12 + 5 = _______','What is twelve plus five?','en','multiple_choice','images/maths/12_plus_5.jpg',NULL,'[\"15\",\"16\",\"17\",\"18\"]','17','Keep 12 in your mind, put up 5 fingers, and count on: 13, 14, 15, 16, 17!','Keep 12 in your mind, put up 5 fingers, and count on: 13, 14, 15, 16, 17!',NULL,0,'Kindergarten 3 (KG3)'),(3,'math_addition','maths','7 + 7 = _______ ?','What is seven plus seven?','en','multiple_choice','images/maths/7_plus_7.jpg',NULL,'[\"12\",\"13\",\"14\",\"15\"]','14','This is a double! Keep 7 in your mind, open 7 fingers, and count on from eight!','This is a double! Keep 7 in your mind, open 7 fingers, and count on from eight!',NULL,0,'Kindergarten 3 (KG3)'),(4,'math_addition','maths','5 + 7 = ?','What is five plus seven?','en','multiple_choice','images/maths/5_plus_7.jpg',NULL,'[\"10\",\"11\",\"12\",\"13\"]','12','Start with the bigger number, 7. Put up 5 fingers, and count on: 8, 9, 10, 11, 12!','Start with the bigger number, 7. Put up 5 fingers, and count on: 8, 9, 10, 11, 12!',NULL,0,'Kindergarten 3 (KG3)'),(5,'math_addition','maths','8 + 0 = ?','What is eight plus zero?','en','multiple_choice','images/maths/8_plus_0.jpg',NULL,'[\"0\",\"7\",\"8\",\"9\"]','8','Zero means nothing is added! So the number 8 stays the same.','Zero means nothing is added! So the number 8 stays the same.',NULL,0,'Kindergarten 3 (KG3)'),(6,'math_subtraction','maths','3 - 1 = ?','What is three minus one?','en','multiple_choice','images/maths/3_minus_1.jpg',NULL,'[\"1\",\"2\",\"3\",\"4\"]','2','Put up 3 fingers, fold down 1 finger. Count how many are left!','Put up 3 fingers, fold down 1 finger. Count how many are left!',NULL,0,'Kindergarten 3 (KG3)'),(7,'math_subtraction','maths','9 - 0 = ?','What is nine minus zero?','en','multiple_choice','images/maths/9_minus_0.jpg',NULL,'[\"0\",\"8\",\"9\",\"10\"]','9','Taking away zero means taking away nothing! So all 9 are still there.','Taking away zero means taking away nothing! So all 9 are still there.',NULL,0,'Kindergarten 3 (KG3)'),(8,'math_subtraction','maths','20 - 10 = ?','What is twenty minus ten?','en','multiple_choice','images/maths/20_minus_10.jpg',NULL,'[\"0\",\"10\",\"20\",\"30\"]','10','20 is two groups of ten. Take away one group of ten, and you have ten left!','20 is two groups of ten. Take away one group of ten, and you have ten left!',NULL,0,'Kindergarten 3 (KG3)'),(9,'math_subtraction','maths','17 - 10 = ?','What is seventeen minus ten?','en','multiple_choice','images/maths/17_minus_10.jpg',NULL,'[\"7\",\"8\",\"10\",\"27\"]','7','17 is 10 and 7. When you take away 10, only 7 are left!','17 is 10 and 7. When you take away 10, only 7 are left!',NULL,0,'Kindergarten 3 (KG3)'),(10,'math_subtraction','maths','12 - 6 = ?','What is twelve minus six?','en','multiple_choice','images/maths/12_minus_6.jpg',NULL,'[\"5\",\"6\",\"7\",\"18\"]','6','Remember doubles: 6 plus 6 makes 12! So when you take away 6, you still have 6 left!','Remember doubles: 6 plus 6 makes 12! So when you take away 6, you still have 6 left!',NULL,0,'Kindergarten 3 (KG3)'),(11,'math_descending','maths','20, 19, 18, ___','Count down: twenty, nineteen, eighteen, what comes next?','en','multiple_choice','images/maths/math_desc_1.jpg',NULL,'[\"16\",\"17\",\"19\",\"21\"]','17','Take one step backward from 18!','Take one step backward from 18!',NULL,0,'Kindergarten 3 (KG3)'),(12,'math_descending','maths','18, 17, ___, 15','Count backward: eighteen, seventeen, blank, fifteen. Which number is missing?','en','multiple_choice','images/maths/math_desc_2.jpg',NULL,'[\"14\",\"16\",\"17\",\"19\"]','16','What number comes between 17 and 15 when counting backward?','What number comes between 17 and 15 when counting backward?',NULL,0,'Kindergarten 3 (KG3)'),(13,'math_descending','maths','16, 15, 14, ___','Count down: sixteen, fifteen, fourteen, what comes next?','en','multiple_choice','images/maths/math_desc_3.jpg',NULL,'[\"12\",\"13\",\"15\",\"17\"]','13','One less than fourteen is thirteen!','One less than fourteen is thirteen!',NULL,0,'Kindergarten 3 (KG3)'),(14,'math_descending','maths','15, ___, 13, 12','Count backward: fifteen, blank, thirteen, twelve. What is the middle number?','en','multiple_choice','images/maths/math_desc_4.jpg',NULL,'[\"11\",\"13\",\"14\",\"16\"]','14','Take one away from 15. What is 15 minus 1?','Take one away from 15. What is 15 minus 1?',NULL,0,'Kindergarten 3 (KG3)'),(15,'math_descending','maths','12, 11, ___, 9','Count down: twelve, eleven, blank, nine. What is the missing number?','en','multiple_choice','images/maths/math_desc_5.jpg',NULL,'[\"8\",\"10\",\"11\",\"13\"]','10','Step backward from 11 to reach the big number ten!','Step backward from 11 to reach the big number ten!',NULL,0,'Kindergarten 3 (KG3)'),(16,'math_descending','maths','11, 10, 9, ___','Count backward: eleven, ten, nine, what comes next?','en','multiple_choice','images/maths/math_desc_6.jpg',NULL,'[\"7\",\"8\",\"9\",\"10\"]','8','The number right before nine is eight!','The number right before nine is eight!',NULL,0,'Kindergarten 3 (KG3)'),(17,'math_descending','maths','10, 9, ___, 7','Count down: ten, nine, blank, seven. Which number is missing?','en','multiple_choice','images/maths/math_desc_7.jpg',NULL,'[\"6\",\"8\",\"9\",\"11\"]','8','Count backward from nine: nine minus one is eight!','Count backward from nine: nine minus one is eight!',NULL,0,'Kindergarten 3 (KG3)'),(18,'math_descending','maths','8, 7, 6, ___','Count backward: eight, seven, six, what comes next?','en','multiple_choice','images/maths/math_desc_8.jpg',NULL,'[\"4\",\"5\",\"6\",\"7\"]','5','A full hand has 5 fingers! Step back from 6 and you reach 5.','A full hand has 5 fingers! Step back from 6 and you reach 5.',NULL,0,'Kindergarten 3 (KG3)'),(19,'math_descending','maths','6, 5, ___, 3','Count down: six, five, blank, three. What number goes in the middle?','en','multiple_choice','images/maths/math_desc_9.jpg',NULL,'[\"2\",\"4\",\"5\",\"6\"]','4','What number sits right between 5 and 3?','What number sits right between 5 and 3?',NULL,0,'Kindergarten 3 (KG3)'),(20,'math_descending','maths','4, 3, 2, ___','Count backward: four, three, two, what is the final number?','en','multiple_choice','images/maths/math_desc_10.jpg',NULL,'[\"0\",\"1\",\"2\",\"3\"]','1','Just one step left to go: four, three, two, one!','Just one step left to go: four, three, two, one!',NULL,0,'Kindergarten 3 (KG3)'),(21,'math_clocks','maths','Morning Wake Up: Draw the hands to show 6:00!','Good morning! The sun is shining. Draw the hands on the clock to show seven o\'clock for wake up time.','en','clock_analog',NULL,NULL,'[\"6:00\"]','6:00','The short hand (hour) points to 6, and the long hand (minute) points straight up to 12!','Point the short hand to six, and the long hand to twelve.','{\"scenario\":\"Morning Wake Up\",\"target_hour\":6,\"target_minute\":0,\"time_str\":\"6:00\",\"icon\":\"🌅\"}',0,'Kindergarten 3 (KG3)'),(22,'math_clocks','maths','School Starts: Draw the hands to show 8:00!','Ding dong! The school bell is ringing. Draw the hands on the clock to show eight o\'clock.','en','clock_analog',NULL,NULL,'[\"8:00\"]','8:00','Point the short hour hand at 8, and the long minute hand straight up at 12.','Point the short hand to eight and the long hand to twelve.','{\"scenario\":\"School Bell Rings\",\"target_hour\":8,\"target_minute\":0,\"time_str\":\"8:00\",\"icon\":\"🏫\"}',0,'Kindergarten 3 (KG3)'),(23,'math_clocks','maths','Snack Time: Draw the hands to show 10:00!','Time for a crunchy apple snack at ten o\'clock! Draw the clock hands to show 10:00.','en','clock_analog',NULL,NULL,'[\"10:00\"]','10:00','Turn the short hand towards 10, and the long hand straight up to 12!','Point the short hand to ten and the long hand to twelve.','{\"scenario\":\"Recess & Snack\",\"target_hour\":10,\"target_minute\":0,\"time_str\":\"10:00\",\"icon\":\"🍎\"}',0,'Kindergarten 3 (KG3)'),(24,'math_clocks','maths','Lunch Time: Draw the hands to show 12:00!','Yum, lunch time! Both the short hand and long hand meet at the top for twelve o\'clock. Draw both hands pointing to 12.','en','clock_analog',NULL,NULL,'[\"12:00\"]','12:00','Both the short hand and long hand point straight up to number 12!','Both hands point straight up to twelve!','{\"scenario\":\"Lunch Time\",\"target_hour\":12,\"target_minute\":0,\"time_str\":\"12:00\",\"icon\":\"🍱\"}',0,'Kindergarten 3 (KG3)'),(25,'math_clocks','maths','Story Time: Draw the hands to show 3:00!','Teacher is opening a magical storybook! Draw the clock hands to show one o\'clock.','en','clock_analog',NULL,NULL,'[\"3:00\"]','3:00','The short hand points to 1, and the long minute hand points straight up to 12.','Point the short hand to one and the long hand to twelve.','{\"scenario\":\"Storybook Time\",\"target_hour\":1,\"target_minute\":0,\"time_str\":\"1:00\",\"icon\":\"📚\"}',0,'Kindergarten 3 (KG3)'),(26,'math_clocks','maths','Nap Time: Draw the hands to show 3:00!','Time for a quiet little afternoon rest! Draw the hands on the clock to show three o\'clock.','en','clock_analog',NULL,NULL,'[\"3:00\"]','3:00','The short hand points to 3, and the long hand points to 12.','Point the short hand to three and the long hand to twelve.','{\"scenario\":\"Cozy Nap Time\",\"target_hour\":3,\"target_minute\":0,\"time_str\":\"3:00\",\"icon\":\"💤\"}',0,'Kindergarten 3 (KG3)'),(27,'math_clocks','maths','Going Home: Draw the hands to show 5:00!','School is finished! Draw the hands on the clock to show five o\'clock.','en','clock_analog',NULL,NULL,'[\"5:00\"]','5:00','Point the short hand directly to 5 on the right, and the long hand straight up to 12.','Point the short hand to five and the long hand to twelve.','{\"scenario\":\"Going Home\",\"target_hour\":5,\"target_minute\":0,\"time_str\":\"5:00\",\"icon\":\"🎒\"}',0,'Kindergarten 3 (KG3)'),(28,'math_clocks','maths','Playground Fun: Draw the hands to show 5:00!','Let\'s play in the playground at five o\'clock! Draw the clock hands to show 5:00.','en','clock_analog',NULL,NULL,'[\"5:00\"]','5:00','Aim the short hour hand towards 5, and the long minute hand at 12.','Point the short hand to five and the long hand to twelve.','{\"scenario\":\"Playground Fun\",\"target_hour\":5,\"target_minute\":0,\"time_str\":\"5:00\",\"icon\":\"🛝\"}',0,'Kindergarten 3 (KG3)'),(29,'math_clocks','maths','Bath Time: Draw the hands to show 6:00!','Splish splash! Time for a warm bath at six o\'clock. Draw the clock hands to show 6:00.','en','clock_analog',NULL,NULL,'[\"6:00\"]','6:00','The short hand points straight down at 6, and the long hand points straight up at 12!','The short hand points straight down to six, and the long hand points to twelve.','{\"scenario\":\"Bath Time\",\"target_hour\":6,\"target_minute\":0,\"time_str\":\"6:00\",\"icon\":\"🛁\"}',0,'Kindergarten 3 (KG3)'),(30,'math_clocks','maths','Bedtime: Draw the hands to show 9:00!','The stars and moon are out! Draw the clock hands to show nine o\'clock for bedtime.','en','clock_analog',NULL,NULL,'[\"9:00\"]','9:00','The short hand points to 9 on the left side, and the long hand points straight up to 12.','Point the short hand to nine and the long hand straight up to twelve.','{\"scenario\":\"Bedtime\",\"target_hour\":9,\"target_minute\":0,\"time_str\":\"9:00\",\"icon\":\"🌙\"}',0,'Kindergarten 3 (KG3)'),(31,'math_clocks','maths','What time is it?','Look at the clock. The long hand points to twelve and the short hand points to six. What time is it?','en','multiple_choice','images/maths/math_clock_1.jpg',NULL,'[\"5:00\",\"6:00\",\"7:00\",\"12:00\"]','6:00','The long hand is on 12, so it is o\'clock! Look at the short hand pointing straight down at 6.','The long hand is on 12, so it is o\'clock! Look at the short hand pointing straight down at 6.',NULL,0,'Kindergarten 3 (KG3)'),(32,'math_clocks','maths','What time is it?','Look at the clock. The long hand is on twelve and the short hand is on five. What time is it?','en','multiple_choice','images/maths/math_clock_2.jpg',NULL,'[\"4:00\",\"5:00\",\"6:00\",\"12:00\"]','5:00','Follow the short red hand. It points straight to number 5!','Follow the short red hand. It points straight to number 5!',NULL,0,'Kindergarten 3 (KG3)'),(33,'math_clocks','maths','What time is it?','Look at the clock. The long hand points to twelve and the short hand points to three. What time is it?','en','multiple_choice','images/maths/math_clock_3.jpg',NULL,'[\"2:00\",\"3:00\",\"4:00\",\"12:00\"]','3:00','The short hand tells the hour. It is pointing directly to the right at 3!','The short hand tells the hour. It is pointing directly to the right at 3!',NULL,0,'Kindergarten 3 (KG3)'),(34,'math_clocks','maths','What time is it?','Look at the clock. The long hand is on twelve and the short hand is on eight. What time is it?','en','multiple_choice','images/maths/math_clock_4.jpg',NULL,'[\"7:00\",\"8:00\",\"9:00\",\"12:00\"]','8:00','Look over on the left side! The short hand is pointing at number 8.','Look over on the left side! The short hand is pointing at number 8.',NULL,0,'Kindergarten 3 (KG3)'),(35,'math_clocks','maths','What time is it?','Look at the clock. Both the long hand and the short hand point to twelve. What time is it?','en','multiple_choice','images/maths/math_clock_4.jpg',NULL,'[\"1:00\",\"6:00\",\"11:00\",\"12:00\"]','12:00','Both hands meet at the very top! That means it is twelve o\'clock.','Both hands meet at the very top! That means it is twelve o\'clock.',NULL,0,'Kindergarten 3 (KG3)'),(36,'bm_bulan','bahasa_melayu','Bulan ke-1 dalam setahun ialah?','Bulan ke-1 dalam setahun ialah?','ms','multiple_choice',NULL,NULL,'[\"Ogos\", \"Mac\", \"Januari\"]','Januari','Kira dari a