INSERT INTO `revisions` VALUES (1,'bm_bulan','Ulang Kaji: 12 Bulan dalam Setahun','Mengecam dan menyusun nama 12 bulan mengikut turutan yang betul.','[{\"title\":\"Bulan ke-1 dalam setahun ialah?\",\"text\":\"Jawapan: Januari • Tip: Kira dari awal: bulan ke-1 ialah Januari.\",\"icon\":\"📅\",\"image_url\":null,\"question_text\":\"Bulan ke-1 dalam setahun ialah?\",\"correct_answer\":\"Januari\",\"hint_text\":\"Kira dari awal: bulan ke-1 ialah Januari.\"},{\"title\":\"Selepas bulan Februari, bulan apa?\",\"text\":\"Jawapan: Mac • Tip: Nyanyi lagu bulan: lepas Februari mestilah Mac!\",\"icon\":\"📅\",\"image_url\":null,\"question_text\":\"Selepas bulan Februari, bulan apa?\",\"correct_answer\":\"Mac\",\"hint_text\":\"Nyanyi lagu bulan: lepas Februari mestilah Mac!\"},{\"title\":\"Sebelum bulan Jun, bulan apa?\",\"text\":\"Jawapan: Mei • Tip: Sebelum Jun ialah Mei.\",\"icon\":\"📅\",\"image_url\":null,\"question_text\":\"Sebelum bulan Jun, bulan apa?\",\"correct_answer\":\"Mei\",\"hint_text\":\"Sebelum Jun ialah Mei.\"},{\"title\":\"Bulan yang bermula dengan huruf J ada Januari, Jun dan?\",\"text\":\"Jawapan: Julai • Tip: Januari, Jun dan Julai.\",\"icon\":\"📅\",\"image_url\":null,\"question_text\":\"Bulan yang bermula dengan huruf J ada Januari, Jun dan?\",\"correct_answer\":\"Julai\",\"hint_text\":\"Januari, Jun dan Julai.\"},{\"title\":\"Susun 3 bulan terakhir dalam setahun:\",\"text\":\"Jawapan: Oktober ➔ November ➔ Disember • Tip: Turutan yang betul: Oktober kemudian November kemudian Disember.\",\"icon\":\"📅\",\"image_url\":null,\"question_text\":\"Susun 3 bulan terakhir dalam setahun:\",\"correct_answer\":\"Oktober ➔ November ➔ Disember\",\"hint_text\":\"Turutan yang betul: Oktober kemudian November kemudian Disember.\"}]'),(2,'bm_suku_kata','Ulang Kaji: Pecahkan Suku Kata','Membina perkataan mudah melalui cantuman dua suku kata terbuka.','[{\"title\":\"Lihat gambar! Lengkapkan perkataan: Ba - ___ ?\",\"text\":\"Jawapan: ju • Tip: Sebut gambar itu: Baju! Jadi Ba + ju.\",\"icon\":\"🧩\",\"image_url\":\"images\\/suku-kata\\/baju.jpg\",\"question_text\":\"Lihat gambar! Lengkapkan perkataan: Ba - ___ ?\",\"correct_answer\":\"ju\",\"hint_text\":\"Sebut gambar itu: Baju! Jadi Ba + ju.\"},{\"title\":\"Lihat gambar! Lengkapkan perkataan: La - ___ ?\",\"text\":\"Jawapan: bu • Tip: Sebut gambar itu: Labu! Jadi La + bu.\",\"icon\":\"🧩\",\"image_url\":\"images\\/suku-kata\\/labu.jpg\",\"question_text\":\"Lihat gambar! Lengkapkan perkataan: La - ___ ?\",\"correct_answer\":\"bu\",\"hint_text\":\"Sebut gambar itu: Labu! Jadi La + bu.\"},{\"title\":\"Lihat gambar! Lengkapkan perkataan: Te - ___ ?\",\"text\":\"Jawapan: bu • Tip: Sebut gambar itu: Tebu! Jadi Te + bu.\",\"icon\":\"🧩\",\"image_url\":\"images\\/suku-kata\\/tebu.jpg\",\"question_text\":\"Lihat gambar! Lengkapkan perkataan: Te - ___ ?\",\"correct_answer\":\"bu\",\"hint_text\":\"Sebut gambar itu: Tebu! Jadi Te + bu.\"},{\"title\":\"Bagaimana pecahkan suku kata bagi \'Kari\'?\",\"text\":\"Jawapan: Ka - ri • Tip: Tepuk tangan dua kali: Ka... ri!\",\"icon\":\"🧩\",\"image_url\":\"images\\/suku-kata\\/kari.jpg\",\"question_text\":\"Bagaimana pecahkan suku kata bagi \'Kari\'?\",\"correct_answer\":\"Ka - ri\",\"hint_text\":\"Tepuk tangan dua kali: Ka... ri!\"},{\"title\":\"Cantumkan suku kata: Ci + li = ?\",\"text\":\"Jawapan: Cili • Tip: Cantumkan bunyi Ci dan li jadi Cili!\",\"icon\":\"🧩\",\"image_url\":\"images\\/suku-kata\\/cili.jpg\",\"question_text\":\"Cantumkan suku kata: Ci + li = ?\",\"correct_answer\":\"Cili\",\"hint_text\":\"Cantumkan bunyi Ci dan li jadi Cili!\"}]'),(3,'bm_kenderaan','Ulang Kaji: Kenderaan Darat, Air & Udara','Kenal pasti jenis kenderaan dan laluan pergerakannya.','[{\"title\":\"Lihat gambar! Kereta bergerak di mana?\",\"text\":\"Jawapan: Darat • Tip: Fikirkan: Adakah ia ada roda di jalan, terapung di air, atau terbang di langit?\",\"icon\":\"🚗\",\"image_url\":\"images\\/kenderaan\\/kereta.jpg\",\"question_text\":\"Lihat gambar! Kereta bergerak di mana?\",\"correct_answer\":\"Darat\",\"hint_text\":\"Fikirkan: Adakah ia ada roda di jalan, terapung di air, atau terbang di langit?\"},{\"title\":\"Lihat gambar! Jentolak bergerak di mana?\",\"text\":\"Jawapan: Darat • Tip: Fikirkan: Adakah ia ada roda di jalan, terapung di air, atau terbang di langit?\",\"icon\":\"🚗\",\"image_url\":\"images\\/kenderaan\\/jentolak.jpg\",\"question_text\":\"Lihat gambar! Jentolak bergerak di mana?\",\"correct_answer\":\"Darat\",\"hint_text\":\"Fikirkan: Adakah ia ada roda di jalan, terapung di air, atau terbang di langit?\"},{\"title\":\"Lihat gambar! Kapal Angkasa bergerak di mana?\",\"text\":\"Jawapan: Udara • Tip: Fikirkan: Adakah ia ada roda di jalan, terapung di air, atau terbang di langit?\",\"icon\":\"🚗\",\"image_url\":\"images\\/kenderaan\\/kapal_angkasa.jpg\",\"question_text\":\"Lihat gambar! Kapal Angkasa bergerak di mana?\",\"correct_answer\":\"Udara\",\"hint_text\":\"Fikirkan: Adakah ia ada roda di jalan, terapung di air, atau terbang di langit?\"},{\"title\":\"Adakah kapal terbang lebih laju daripada basikal?\",\"text\":\"Jawapan: Ya, lebih laju • Tip: Kapal terbang terbang sangat laju di awan!\",\"icon\":\"🚗\",\"image_url\":null,\"question_text\":\"Adakah kapal terbang lebih laju daripada basikal?\",\"correct_answer\":\"Ya, lebih laju\",\"hint_text\":\"Kapal terbang terbang sangat laju di awan!\"},{\"title\":\"Kereta api membawa ramai orang di dalam banyak?\",\"text\":\"Jawapan: Gerabak • Tip: Kereta api ada banyak gerabak bersambung.\",\"icon\":\"🚗\",\"image_url\":null,\"question_text\":\"Kereta api membawa ramai orang di dalam banyak?\",\"correct_answer\":\"Gerabak\",\"hint_text\":\"Kereta api ada banyak gerabak bersambung.\"}]'),(4,'bm_binatang','Ulang Kaji: Haiwan 2 Kaki & 4 Kaki','Mengelaskan pelbagai haiwan mengikut bilangan kakinya.','[{\"title\":\"Lihat gambar! Ayam ada berapa kaki?\",\"text\":\"Jawapan: 2 kaki • Tip: Kira kaki Ayam dalam gambar!\",\"icon\":\"🐾\",\"image_url\":\"images\\/binatang\\/ayam.jpg\",\"question_text\":\"Lihat gambar! Ayam ada berapa kaki?\",\"correct_answer\":\"2 kaki\",\"hint_text\":\"Kira kaki Ayam dalam gambar!\"},{\"title\":\"Lihat gambar! Kuda ada berapa kaki?\",\"text\":\"Jawapan: 4 kaki • Tip: Kira kaki Kuda dalam gambar!\",\"icon\":\"🐾\",\"image_url\":\"images\\/binatang\\/kuda.jpg\",\"question_text\":\"Lihat gambar! Kuda ada berapa kaki?\",\"correct_answer\":\"4 kaki\",\"hint_text\":\"Kira kaki Kuda dalam gambar!\"},{\"title\":\"Lihat gambar! Zirafah ada berapa kaki?\",\"text\":\"Jawapan: 4 kaki • Tip: Kira kaki Zirafah dalam gambar!\",\"icon\":\"🐾\",\"image_url\":\"images\\/binatang\\/zirafah.jpg\",\"question_text\":\"Lihat gambar! Zirafah ada berapa kaki?\",\"correct_answer\":\"4 kaki\",\"hint_text\":\"Kira kaki Zirafah dalam gambar!\"},{\"title\":\"Burung terbang di udara menggunakan apa?\",\"text\":\"Jawapan: Sayap • Tip: Burung mengepakkan sayapnya di udara.\",\"icon\":\"🐾\",\"image_url\":null,\"question_text\":\"Burung terbang di udara menggunakan apa?\",\"correct_answer\":\"Sayap\",\"hint_text\":\"Burung mengepakkan sayapnya di udara.\"},{\"title\":\"Haiwan manakah yang mengeluarkan dakwat hitam di laut?\",\"text\":\"Jawapan: Sotong • Tip: Sotong pancutkan dakwat bila terkejut.\",\"icon\":\"🐾\",\"image_url\":null,\"question_text\":\"Haiwan manakah yang mengeluarkan dakwat hitam di laut?\",\"correct_answer\":\"Sotong\",\"hint_text\":\"Sotong pancutkan dakwat bila terkejut.\"}]'),(5,'bm_ini_itu','Ulang Kaji: Kata Tunjuk: Ini & Itu','Memahami perbezaan jarak dekat (Ini) dan jarak jauh (Itu).','[{\"title\":\"Lihat gambar! Benda ini ini atau itu?\",\"text\":\"Jawapan: Ini • Tip: Basikal ada dekat dengan saya. Jika dekat sebut \'Ini\', jika jauh sebut \'Itu\'.\",\"icon\":\"👉\",\"image_url\":\"images\\/ini-itu\\/basikal_dekat.jpg\",\"question_text\":\"Lihat gambar! Benda ini ini atau itu?\",\"correct_answer\":\"Ini\",\"hint_text\":\"Basikal ada dekat dengan saya. Jika dekat sebut \'Ini\', jika jauh sebut \'Itu\'.\"},{\"title\":\"Lihat gambar! Benda ini itu atau ini?\",\"text\":\"Jawapan: Itu • Tip: Bunga ros mekar jauh di taman. Jika dekat sebut \'Ini\', jika jauh sebut \'Itu\'.\",\"icon\":\"👉\",\"image_url\":\"images\\/ini-itu\\/bunga_ros_jauh.jpg\",\"question_text\":\"Lihat gambar! Benda ini itu atau ini?\",\"correct_answer\":\"Itu\",\"hint_text\":\"Bunga ros mekar jauh di taman. Jika dekat sebut \'Ini\', jika jauh sebut \'Itu\'.\"},{\"title\":\"Topi yang ada di atas kepala saya: \'___ topi saya.\'\",\"text\":\"Jawapan: Ini • Tip: Topi di kepala sendiri sebut \'Ini\'.\",\"icon\":\"👉\",\"image_url\":null,\"question_text\":\"Topi yang ada di atas kepala saya: \'___ topi saya.\'\",\"correct_answer\":\"Ini\",\"hint_text\":\"Topi di kepala sendiri sebut \'Ini\'.\"},{\"title\":\"Mainan blok yang sedang saya susun: \'___ mainan saya.\'\",\"text\":\"Jawapan: Ini • Tip: Mainan sedang kita main sebut \'Ini\'.\",\"icon\":\"👉\",\"image_url\":null,\"question_text\":\"Mainan blok yang sedang saya susun: \'___ mainan saya.\'\",\"correct_answer\":\"Ini\",\"hint_text\":\"Mainan sedang kita main sebut \'Ini\'.\"},{\"title\":\"Bunga mekar di pokok tinggi seberang sana: \'___ bunga raya.\'\",\"text\":\"Jawapan: Itu • Tip: Bunga jauh di seberang sana sebut \'Itu\'.\",\"icon\":\"👉\",\"image_url\":null,\"question_text\":\"Bunga mekar di pokok tinggi seberang sana: \'___ bunga raya.\'\",\"correct_answer\":\"Itu\",\"hint_text\":\"Bunga jauh di seberang sana sebut \'Itu\'.\"}]'),(6,'math_clocks','Revision: Analog Clocks & Time','Learn the hour hand, minute hand, and how to read the clock.','[{\"title\":\"Morning Wake Up: Draw the hands to show 6:00!\",\"text\":\"Answer: 6:00 • Hint: The short hand (hour) points to 6, and the long hand (minute) points straight up to 12!\",\"icon\":\"🕒\",\"image_url\":null,\"question_text\":\"Morning Wake Up: Draw the hands to show 6:00!\",\"correct_answer\":\"6:00\",\"hint_text\":\"The short hand (hour) points to 6, and the long hand (minute) points straight up to 12!\"},{\"title\":\"Story Time: Draw the hands to show 3:00!\",\"text\":\"Answer: 3:00 • Hint: The short hand points to 1, and the long minute hand points straight up to 12.\",\"icon\":\"🕒\",\"image_url\":null,\"question_text\":\"Story Time: Draw the hands to show 3:00!\",\"correct_answer\":\"3:00\",\"hint_text\":\"The short hand points to 1, and the long minute hand points straight up to 12.\"},{\"title\":\"Playground Fun: Draw the hands to show 5:00!\",\"text\":\"Answer: 5:00 • Hint: Aim the short hour hand towards 5, and the long minute hand at 12.\",\"icon\":\"🕒\",\"image_url\":null,\"question_text\":\"Playground Fun: Draw the hands to show 5:00!\",\"correct_answer\":\"5:00\",\"hint_text\":\"Aim the short hour hand towards 5, and the long minute hand at 12.\"},{\"title\":\"What time is it?\",\"text\":\"Answer: 5:00 • Hint: Follow the short red hand. It points straight to number 5!\",\"icon\":\"🕒\",\"image_url\":\"images\\/maths\\/math_clock_2.jpg\",\"question_text\":\"What time is it?\",\"correct_answer\":\"5:00\",\"hint_text\":\"Follow the short red hand. It points straight to number 5!\"},{\"title\":\"What time is it?\",\"text\":\"Answer: 12:00 • Hint: Both hands meet at the very top! That means it is twelve o\'clock.\",\"icon\":\"🕒\",\"image_url\":\"images\\/maths\\/math_clock_4.jpg\",\"question_text\":\"What time is it?\",\"correct_answer\":\"12:00\",\"hint_text\":\"Both hands meet at the very top! That means it is twelve o\'clock.\"}]'),(7,'math_descending','Revision: Descending Numbers (20 to 1)','Count numbers from largest to smallest, from 20 down to 1.','[{\"title\":\"20, 19, 18, ___\",\"text\":\"Answer: 17 • Hint: Take one step backward from 18!\",\"icon\":\"📉\",\"image_url\":\"images\\/maths\\/math_desc_1.jpg\",\"question_text\":\"20, 19, 18, ___\",\"correct_answer\":\"17\",\"hint_text\":\"Take one step backward from 18!\"},{\"title\":\"16, 15, 14, ___\",\"text\":\"Answer: 13 • Hint: One less than fourteen is thirteen!\",\"icon\":\"📉\",\"image_url\":\"images\\/maths\\/math_desc_3.jpg\",\"question_text\":\"16, 15, 14, ___\",\"correct_answer\":\"13\",\"hint_text\":\"One less than fourteen is thirteen!\"},{\"title\":\"11, 10, 9, ___\",\"text\":\"Answer: 8 • Hint: The number right before nine is eight!\",\"icon\":\"📉\",\"image_url\":\"images\\/maths\\/math_desc_6.jpg\",\"question_text\":\"11, 10, 9, ___\",\"correct_answer\":\"8\",\"hint_text\":\"The number right before nine is eight!\"},{\"title\":\"8, 7, 6, ___\",\"text\":\"Answer: 5 • Hint: A full hand has 5 fingers! Step back from 6 and you reach 5.\",\"icon\":\"📉\",\"image_url\":\"images\\/maths\\/math_desc_8.jpg\",\"question_text\":\"8, 7, 6, ___\",\"correct_answer\":\"5\",\"hint_text\":\"A full hand has 5 fingers! Step back from 6 and you reach 5.\"},{\"title\":\"4, 3, 2, ___\",\"text\":\"Answer: 1 • Hint: Just one step left to go: four, three, two, one!\",\"icon\":\"📉\",\"image_url\":\"images\\/maths\\/math_desc_10.jpg\",\"question_text\":\"4, 3, 2, ___\",\"correct_answer\":\"1\",\"hint_text\":\"Just one step left to go: four, three, two, one!\"}]'),(8,'math_addition','Revision: Addition (Combining Numbers)','Count and add groups of fun objects together.','[{\"title\":\"What is 8 + 3 = _______\",\"text\":\"Answer: 11 • Hint: Keep 8 in your mind, put up 3 fingers, and count forward!\",\"icon\":\"➕\",\"image_url\":\"images\\/maths\\/8_plus_3.jpg\",\"question_text\":\"What is 8 + 3 = _______\",\"correct_answer\":\"11\",\"hint_text\":\"Keep 8 in your mind, put up 3 fingers, and count forward!\"},{\"title\":\"What is 1 + 2?\",\"text\":\"Answer: 3 • Hint: Count on your fingers: 1, 2, 3!\",\"icon\":\"➕\",\"image_url\":null,\"question_text\":\"What is 1 + 2?\",\"correct_answer\":\"3\",\"hint_text\":\"Count on your fingers: 1, 2, 3!\"},{\"title\":\"What is 1 + 3?\",\"text\":\"Answer: 4 • Hint: Count 1 and add 3 more: 4!\",\"icon\":\"➕\",\"image_url\":null,\"question_text\":\"What is 1 + 3?\",\"correct_answer\":\"4\",\"hint_text\":\"Count 1 and add 3 more: 4!\"},{\"title\":\"What is 1 + 9?\",\"text\":\"Answer: 10 • Hint: Count 1 and add 9 more: 10!\",\"icon\":\"➕\",\"image_url\":null,\"question_text\":\"What is 1 + 9?\",\"correct_answer\":\"10\",\"hint_text\":\"Count 1 and add 9 more: 10!\"},{\"title\":\"What is 15 + 1?\",\"text\":\"Answer: 16 • Hint: Count 15 and add 1 more: 16!\",\"icon\":\"➕\",\"image_url\":null,\"question_text\":\"What is 15 + 1?\",\"correct_answer\":\"16\",\"hint_text\":\"Count 15 and add 1 more: 16!\"}]'),(9,'math_subtraction','Revision: Subtraction (Taking Away)','Count what remains when items are removed or popped.','[{\"title\":\"3 - 1 = ?\",\"text\":\"Answer: 2 • Hint: Put up 3 fingers, fold down 1 finger. Count how many are left!\",\"icon\":\"➖\",\"image_url\":\"images\\/maths\\/3_minus_1.jpg\",\"question_text\":\"3 - 1 = ?\",\"correct_answer\":\"2\",\"hint_text\":\"Put up 3 fingers, fold down 1 finger. Count how many are left!\"},{\"title\":\"What is 4 - 1?\",\"text\":\"Answer: 3 • Hint: 4 take away 1 is 3!\",\"icon\":\"➖\",\"image_url\":null,\"question_text\":\"What is 4 - 1?\",\"correct_answer\":\"3\",\"hint_text\":\"4 take away 1 is 3!\"},{\"title\":\"What is 6 - 4?\",\"text\":\"Answer: 2 • Hint: Start at 6 and count back 4: 2!\",\"icon\":\"➖\",\"image_url\":null,\"question_text\":\"What is 6 - 4?\",\"correct_answer\":\"2\",\"hint_text\":\"Start at 6 and count back 4: 2!\"},{\"title\":\"What is 10 - 7?\",\"text\":\"Answer: 3 • Hint: Start at 10 and count back 7: 3!\",\"icon\":\"➖\",\"image_url\":null,\"question_text\":\"What is 10 - 7?\",\"correct_answer\":\"3\",\"hint_text\":\"Start at 10 and count back 7: 3!\"},{\"title\":\"What is 20 - 10?\",\"text\":\"Answer: 10 • Hint: Start at 20 and count back 10: 10!\",\"icon\":\"➖\",\"image_url\":null,\"question_text\":\"What is 20 - 10?\",\"correct_answer\":\"10\",\"hint_text\":\"Start at 20 and count back 10: 10!\"}]'),(10,'eng_days_months','Revision: Days of Week & Months','Learn the 7 days of the week in sequence and match months to their numbers.','[{\"title\":\"What day comes after Monday?\",\"text\":\"Answer: Tuesday • Hint: Sing the days of the week: after Monday is Tuesday!\",\"icon\":\"🗓️\",\"image_url\":null,\"question_text\":\"What day comes after Monday?\",\"correct_answer\":\"Tuesday\",\"hint_text\":\"Sing the days of the week: after Monday is Tuesday!\"},{\"title\":\"Which days start with the letter \'T\'?\",\"text\":\"Answer: Tuesday and Thursday • Hint: Tuesday and Thursday both start with T!\",\"icon\":\"🗓️\",\"image_url\":null,\"question_text\":\"Which days start with the letter \'T\'?\",\"correct_answer\":\"Tuesday and Thursday\",\"hint_text\":\"Tuesday and Thursday both start with T!\"},{\"title\":\"What is the 8th month of the year?\",\"text\":\"Answer: August • Hint: Count on the calendar: month number 8 is August.\",\"icon\":\"🗓️\",\"image_url\":null,\"question_text\":\"What is the 8th month of the year?\",\"correct_answer\":\"August\",\"hint_text\":\"Count on the calendar: month number 8 is August.\"},{\"title\":\"Christmas is celebrated in which month?\",\"text\":\"Answer: December • Hint: Christmas is on December 25th!\",\"icon\":\"🗓️\",\"image_url\":null,\"question_text\":\"Christmas is celebrated in which month?\",\"correct_answer\":\"December\",\"hint_text\":\"Christmas is on December 25th!\"},{\"title\":\"What day is today if yesterday was Monday?\",\"text\":\"Answer: Tuesday • Hint: After Monday is Tuesday!\",\"icon\":\"🗓️\",\"image_url\":null,\"question_text\":\"What day is today if yesterday was Monday?\",\"correct_answer\":\"Tuesday\",\"hint_text\":\"After Monday is Tuesday!\"}]'),(11,'eng_blending','Revision: Beginning Blends (ch- & th-)','Recognise and match beginning blend sounds: ch- (chair) and th- (thorn).','[{\"title\":\"Sound it out: c - a - t. What word is it?\",\"text\":\"Answer: cat • Hint: A cute pet that says meow!\",\"icon\":\"🗣️\",\"image_url\":\"images\\/english\\/cat.jpg\",\"question_text\":\"Sound it out: c - a - t. What word is it?\",\"correct_answer\":\"cat\",\"hint_text\":\"A cute pet that says meow!\"},{\"title\":\"Sound it out: m - o - p. What word is it?\",\"text\":\"Answer: mop • Hint: Used to clean wet floors.\",\"icon\":\"🗣️\",\"image_url\":null,\"question_text\":\"Sound it out: m - o - p. What word is it?\",\"correct_answer\":\"mop\",\"hint_text\":\"Used to clean wet floors.\"},{\"title\":\"What is the first letter sound of \'Moon\'?\",\"text\":\"Answer: M • Hint: M is for Moon!\",\"icon\":\"🗣️\",\"image_url\":\"images\\/science\\/moon.jpg\",\"question_text\":\"What is the first letter sound of \'Moon\'?\",\"correct_answer\":\"M\",\"hint_text\":\"M is for Moon!\"},{\"title\":\"Which word rhymes with \'Fox\'?\",\"text\":\"Answer: Box • Hint: Fox and Box both say -ox!\",\"icon\":\"🗣️\",\"image_url\":null,\"question_text\":\"Which word rhymes with \'Fox\'?\",\"correct_answer\":\"Box\",\"hint_text\":\"Fox and Box both say -ox!\"},{\"title\":\"Fill in the vowel for Pin: p - __ - n\",\"text\":\"Answer: i • Hint: Pin has letter \'i\'!\",\"icon\":\"🗣️\",\"image_url\":null,\"question_text\":\"Fill in the vowel for Pin: p - __ - n\",\"correct_answer\":\"i\",\"hint_text\":\"Pin has letter \'i\'!\"}]'),(12,'eng_pronouns','Revision: Pronouns (He, She, It, They)','Choose the correct pronoun for boys, girls, objects, and groups.','[{\"title\":\"Ben is a little boy. We say: (He \\/ She \\/ It)\",\"text\":\"Answer: He • Hint: Use \'He\' for a boy or man!\",\"icon\":\"👥\",\"image_url\":\"images\\/english\\/little_boy.jpg\",\"question_text\":\"Ben is a little boy. We say: (He \\/ She \\/ It)\",\"correct_answer\":\"He\",\"hint_text\":\"Use \'He\' for a boy or man!\"},{\"title\":\"My sister is singing a song. ___ sings nicely.\",\"text\":\"Answer: She • Hint: Sister is a girl: use \'She\'.\",\"icon\":\"👥\",\"image_url\":null,\"question_text\":\"My sister is singing a song. ___ sings nicely.\",\"correct_answer\":\"She\",\"hint_text\":\"Sister is a girl: use \'She\'.\"},{\"title\":\"The house has a red roof. ___ is big and cozy.\",\"text\":\"Answer: It • Hint: A house is a building: use \'It\'.\",\"icon\":\"👥\",\"image_url\":\"images\\/english\\/house.jpg\",\"question_text\":\"The house has a red roof. ___ is big and cozy.\",\"correct_answer\":\"It\",\"hint_text\":\"A house is a building: use \'It\'.\"},{\"title\":\"Look at the girl skipping rope. ___ is smiling! (She \\/ He)\",\"text\":\"Answer: She • Hint: Girl: She!\",\"icon\":\"👥\",\"image_url\":null,\"question_text\":\"Look at the girl skipping rope. ___ is smiling! (She \\/ He)\",\"correct_answer\":\"She\",\"hint_text\":\"Girl: She!\"},{\"title\":\"Here is a fresh yellow banana. ___ tastes yummy! (It \\/ He)\",\"text\":\"Answer: It • Hint: Banana: It!\",\"icon\":\"👥\",\"image_url\":null,\"question_text\":\"Here is a fresh yellow banana. ___ tastes yummy! (It \\/ He)\",\"correct_answer\":\"It\",\"hint_text\":\"Banana: It!\"}]'),(13,'eng_articles','Revision: Articles: A and An','Use \"an\" before vowel sounds (a, e, i, o, u) and \"a\" before consonants.','[{\"title\":\"___ apple\",\"text\":\"Answer: An • Hint: \'Apple\' starts with vowel A: use \'An\'!\",\"icon\":\"🔤\",\"image_url\":\"images\\/english\\/apple.jpg\",\"question_text\":\"___ apple\",\"correct_answer\":\"An\",\"hint_text\":\"\'Apple\' starts with vowel A: use \'An\'!\"},{\"title\":\"Look at ___ elephant in the zoo!\",\"text\":\"Answer: an • Hint: Use \'an\' before elephant!\",\"icon\":\"🔤\",\"image_url\":\"images\\/binatang\\/gajah.jpg\",\"question_text\":\"Look at ___ elephant in the zoo!\",\"correct_answer\":\"an\",\"hint_text\":\"Use \'an\' before elephant!\"},{\"title\":\"___ flower\",\"text\":\"Answer: A • Hint: \'Flower\' starts with F: use \'A\'!\",\"icon\":\"🔤\",\"image_url\":\"images\\/science\\/flower.jpg\",\"question_text\":\"___ flower\",\"correct_answer\":\"A\",\"hint_text\":\"\'Flower\' starts with F: use \'A\'!\"},{\"title\":\"___ star\",\"text\":\"Answer: A • Hint: Star starts with S: A!\",\"icon\":\"🔤\",\"image_url\":null,\"question_text\":\"___ star\",\"correct_answer\":\"A\",\"hint_text\":\"Star starts with S: A!\"},{\"title\":\"Do we say \'a dog\' or \'an dog\'?\",\"text\":\"Answer: a dog • Hint: We say \'a dog\'!\",\"icon\":\"🔤\",\"image_url\":null,\"question_text\":\"Do we say \'a dog\' or \'an dog\'?\",\"correct_answer\":\"a dog\",\"hint_text\":\"We say \'a dog\'!\"}]'),(14,'eng_has_have','Revision: Using Has and Have','He/She/It uses \"has\", while I/We/They uses \"have\".','[{\"title\":\"I ___ two hands to clap. (have \\/ has)\",\"text\":\"Answer: have • Hint: Say: \'I have\'!\",\"icon\":\"🤲\",\"image_url\":null,\"question_text\":\"I ___ two hands to clap. (have \\/ has)\",\"correct_answer\":\"have\",\"hint_text\":\"Say: \'I have\'!\"},{\"title\":\"She ___ a storybook to read. (has \\/ have)\",\"text\":\"Answer: has • Hint: A girl: \'She has\'!\",\"icon\":\"🤲\",\"image_url\":null,\"question_text\":\"She ___ a storybook to read. (has \\/ have)\",\"correct_answer\":\"has\",\"hint_text\":\"A girl: \'She has\'!\"},{\"title\":\"The boy ___ a yellow kite. (has \\/ have)\",\"text\":\"Answer: has • Hint: Boy: \'has\'.\",\"icon\":\"🤲\",\"image_url\":null,\"question_text\":\"The boy ___ a yellow kite. (has \\/ have)\",\"correct_answer\":\"has\",\"hint_text\":\"Boy: \'has\'.\"},{\"title\":\"My brother ___ a robot toy. (has \\/ have)\",\"text\":\"Answer: has • Hint: Brother: \'has\'.\",\"icon\":\"🤲\",\"image_url\":null,\"question_text\":\"My brother ___ a robot toy. (has \\/ have)\",\"correct_answer\":\"has\",\"hint_text\":\"Brother: \'has\'.\"},{\"title\":\"You ___ a birthday party coming! (have \\/ has)\",\"text\":\"Answer: have • Hint: \'You have\'.\",\"icon\":\"🤲\",\"image_url\":null,\"question_text\":\"You ___ a birthday party coming! (have \\/ has)\",\"correct_answer\":\"have\",\"hint_text\":\"\'You have\'.\"}]'),(15,'eng_demonstratives','Revision: This, That, These, Those','Master near vs far, singular vs plural pointer words.','[{\"title\":\"Hold in your hand: \'___ is my pencil.\' (This \\/ That)\",\"text\":\"Answer: This • Hint: Holding close in your hand: say \'This\'!\",\"icon\":\"👉\",\"image_url\":\"images\\/english\\/color_pencils.jpg\",\"question_text\":\"Hold in your hand: \'___ is my pencil.\' (This \\/ That)\",\"correct_answer\":\"This\",\"hint_text\":\"Holding close in your hand: say \'This\'!\"},{\"title\":\"On top of the roof far away: \'___ is a little bird.\' (That \\/ This)\",\"text\":\"Answer: That • Hint: High on the roof: say \'That\'!\",\"icon\":\"👉\",\"image_url\":null,\"question_text\":\"On top of the roof far away: \'___ is a little bird.\' (That \\/ This)\",\"correct_answer\":\"That\",\"hint_text\":\"High on the roof: say \'That\'!\"},{\"title\":\"Right in front of me: \'___ are my drawing papers.\' (These \\/ Those)\",\"text\":\"Answer: These • Hint: Papers right here: say \'These\'!\",\"icon\":\"👉\",\"image_url\":null,\"question_text\":\"Right in front of me: \'___ are my drawing papers.\' (These \\/ Those)\",\"correct_answer\":\"These\",\"hint_text\":\"Papers right here: say \'These\'!\"},{\"title\":\"Point to a plane far in the sky: \'___ is a plane.\' (That \\/ This)\",\"text\":\"Answer: That • Hint: Plane far away: That!\",\"icon\":\"👉\",\"image_url\":null,\"question_text\":\"Point to a plane far in the sky: \'___ is a plane.\' (That \\/ This)\",\"correct_answer\":\"That\",\"hint_text\":\"Plane far away: That!\"},{\"title\":\"Wear your watch: \'___ is my watch.\' (This \\/ That)\",\"text\":\"Answer: This • Hint: Wearing watch: This!\",\"icon\":\"👉\",\"image_url\":null,\"question_text\":\"Wear your watch: \'___ is my watch.\' (This \\/ That)\",\"correct_answer\":\"This\",\"hint_text\":\"Wearing watch: This!\"}]'),(16,'eng_comprehension','Revision: Reading Comprehension','Read sweet passages, understand context, and answer smart questions.','[{\"title\":\"What color is Ben\'s car?\",\"text\":\"Answer: Red • Hint: Ben\'s car is red!\",\"icon\":\"📖\",\"image_url\":null,\"question_text\":\"What color is Ben\'s car?\",\"correct_answer\":\"Red\",\"hint_text\":\"Ben\'s car is red!\"},{\"title\":\"Where does Pip fly?\",\"text\":\"Answer: High in the sky • Hint: Pip flies high in the sky.\",\"icon\":\"📖\",\"image_url\":null,\"question_text\":\"Where does Pip fly?\",\"correct_answer\":\"High in the sky\",\"hint_text\":\"Pip flies high in the sky.\"},{\"title\":\"Where does Anna play with her duck?\",\"text\":\"Answer: In the bathtub • Hint: In the bathtub.\",\"icon\":\"📖\",\"image_url\":null,\"question_text\":\"Where does Anna play with her duck?\",\"correct_answer\":\"In the bathtub\",\"hint_text\":\"In the bathtub.\"},{\"title\":\"Where does the bee fly?\",\"text\":\"Answer: From flower to flower • Hint: Flower to flower.\",\"icon\":\"📖\",\"image_url\":null,\"question_text\":\"Where does the bee fly?\",\"correct_answer\":\"From flower to flower\",\"hint_text\":\"Flower to flower.\"},{\"title\":\"Is a rainbow colorful or black?\",\"text\":\"Answer: Colorful • Hint: A rainbow has many colors!\",\"icon\":\"📖\",\"image_url\":null,\"question_text\":\"Is a rainbow colorful or black?\",\"correct_answer\":\"Colorful\",\"hint_text\":\"A rainbow has many colors!\"}]'),(17,'sci_land_sea','Revision: Land vs Sea Animals','Identify whether animals live on land or in the ocean.','[{\"title\":\"Look at the picture! Does a fish live on Land or in Water?\",\"text\":\"Answer: Water • Hint: A fish swims in water using fins!\",\"icon\":\"🐬\",\"image_url\":\"images\\/binatang\\/ikan.jpg\",\"question_text\":\"Look at the picture! Does a fish live on Land or in Water?\",\"correct_answer\":\"Water\",\"hint_text\":\"A fish swims in water using fins!\"},{\"title\":\"Look at the picture! Does a monkey live on Land or in Water?\",\"text\":\"Answer: Land • Hint: A monkey climbs trees on land!\",\"icon\":\"🐬\",\"image_url\":\"images\\/binatang\\/monyet.jpg\",\"question_text\":\"Look at the picture! Does a monkey live on Land or in Water?\",\"correct_answer\":\"Land\",\"hint_text\":\"A monkey climbs trees on land!\"},{\"title\":\"Which animal has 8 arms and lives under the sea?\",\"text\":\"Answer: Octopus • Hint: An octopus lives in the sea.\",\"icon\":\"🐬\",\"image_url\":null,\"question_text\":\"Which animal has 8 arms and lives under the sea?\",\"correct_answer\":\"Octopus\",\"hint_text\":\"An octopus lives in the sea.\"},{\"title\":\"Which sea animal has sharp teeth and fins?\",\"text\":\"Answer: Shark • Hint: Sharks swim in the sea.\",\"icon\":\"🐬\",\"image_url\":null,\"question_text\":\"Which sea animal has sharp teeth and fins?\",\"correct_answer\":\"Shark\",\"hint_text\":\"Sharks swim in the sea.\"},{\"title\":\"Do all fish have fins to help them swim?\",\"text\":\"Answer: Yes • Hint: Fish use fins to swim!\",\"icon\":\"🐬\",\"image_url\":null,\"question_text\":\"Do all fish have fins to help them swim?\",\"correct_answer\":\"Yes\",\"hint_text\":\"Fish use fins to swim!\"}]'),(18,'sci_sink_float','Revision: Sink or Float','Discover which objects sink to the bottom or float on water.','[{\"title\":\"Look at the picture! Drop a heavy metal key 🗝️ in water. Does it sink or float?\",\"text\":\"Answer: Sinks • Hint: Heavy metal keys sink straight to the bottom!\",\"icon\":\"⚓\",\"image_url\":\"images\\/science\\/sink_key.jpg\",\"question_text\":\"Look at the picture! Drop a heavy metal key 🗝️ in water. Does it sink or float?\",\"correct_answer\":\"Sinks\",\"hint_text\":\"Heavy metal keys sink straight to the bottom!\"},{\"title\":\"Look at the picture! Does a solid brick sink or float?\",\"text\":\"Answer: Sinks • Hint: A heavy brick sinks immediately!\",\"icon\":\"⚓\",\"image_url\":\"images\\/science\\/brick.jpg\",\"question_text\":\"Look at the picture! Does a solid brick sink or float?\",\"correct_answer\":\"Sinks\",\"hint_text\":\"A heavy brick sinks immediately!\"},{\"title\":\"Look at the picture! Does a coconut float in ocean water?\",\"text\":\"Answer: Floats • Hint: Coconuts float across the sea to new islands!\",\"icon\":\"⚓\",\"image_url\":\"images\\/science\\/coconut.jpg\",\"question_text\":\"Look at the picture! Does a coconut float in ocean water?\",\"correct_answer\":\"Floats\",\"hint_text\":\"Coconuts float across the sea to new islands!\"},{\"title\":\"Look at the picture! Does a tree log float down the river?\",\"text\":\"Answer: Floats • Hint: Tree logs float on river water.\",\"icon\":\"⚓\",\"image_url\":\"images\\/science\\/float_wood.jpg\",\"question_text\":\"Look at the picture! Does a tree log float down the river?\",\"correct_answer\":\"Floats\",\"hint_text\":\"Tree logs float on river water.\"},{\"title\":\"Look at the picture! If a stone drops to the bottom of the bowl, we say it:\",\"text\":\"Answer: Sinks • Hint: It sinks!\",\"icon\":\"⚓\",\"image_url\":\"images\\/science\\/sink_stone.jpg\",\"question_text\":\"Look at the picture! If a stone drops to the bottom of the bowl, we say it:\",\"correct_answer\":\"Sinks\",\"hint_text\":\"It sinks!\"}]'),(19,'sci_celestial','Revision: Sun, Moon, Star & Earth','Learn about the celestial bodies in our sky and our home planet Earth.','[{\"title\":\"Core Concept\",\"text\":\"Learn about the celestial bodies in our sky and our home planet Earth.\",\"icon\":\"🌍\",\"image_url\":null}]'),(20,'sci_materials','Revision: Materials: Metal, Glass & Paper','Identify everyday objects made of metal, transparent glass, or paper.','[{\"title\":\"Core Concept\",\"text\":\"Identify everyday objects made of metal, transparent glass, or paper.\",\"icon\":\"🪨\",\"image_url\":null}]'),(21,'sci_pollution','Revision: Types of Pollution','Learn about air pollution, water/sea pollution, and land pollution.','[{\"title\":\"Core Concept\",\"text\":\"Learn about air pollution, water\\/sea pollution, and land pollution.\",\"icon\":\"🏭\",\"image_url\":null}]'),(22,'sci_plants','Revision: Parts & Needs of a Plant','Identify roots, stem, leaves, flower, fruit and sunlight, air, water.','[{\"title\":\"Core Concept\",\"text\":\"Identify roots, stem, leaves, flower, fruit and sunlight, air, water.\",\"icon\":\"🌱\",\"image_url\":null}]'),(23,'ict_storage','Revision: Computer Drives & Storage','Learn about Hard disk drives, floppy disks, CD-ROMs, memory cards, and USB pendrives.','[{\"title\":\"Core Concept\",\"text\":\"Learn about Hard disk drives, floppy disks, CD-ROMs, memory cards, and USB pendrives.\",\"icon\":\"💾\",\"image_url\":null}]'),(24,'ict_parts','Revision: All About Computer Parts','Identify monitors, keyboards, printers, headphones, scanners, and system units.','[{\"title\":\"Core Concept\",\"text\":\"Identify monitors, keyboards, printers, headphones, scanners, and system units.\",\"icon\":\"🖥️\",\"image_url\":null}]'),(25,'ict_counting','Revision: Count Computer Peripherals','Count and determine the correct number of computer devices.','[{\"title\":\"Core Concept\",\"text\":\"Count and determine the correct number of computer devices.\",\"icon\":\"🔢\",\"image_url\":null}]'),(26,'ict_spelling','Revision: Fill in the Missing Letters','Complete the missing letters for computer peripheral names.','[{\"title\":\"Core Concept\",\"text\":\"Complete the missing letters for computer peripheral names.\",\"icon\":\"🔤\",\"image_url\":null}]'),(27,'ict_input_output','Revision: Input (I) vs Output (O) Devices','Recognise whether a device feeds data in (Input) or presents results (Output).','[{\"title\":\"Core Concept\",\"text\":\"Recognise whether a device feeds data in (Input) or presents results (Output).\",\"icon\":\"🔌\",\"image_url\":null}]'),(28,'psr_math_numbers','5-Minute Quick Revision: Numbers, Place Value & BODMAS','Essential Year 6 Brunei PSR revision flashcards for Numbers, Place Value & BODMAS. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"What is the place value of digit 7 in 4,782,105?\",\n        \"key_fact\": \"Hundred thousands\",\n        \"explanation\": \"Count places from right: 5 (ones), 0 (tens), 1 (hundreds), 2 (thousands), 8 (ten thousands), 7 (hundred thousands).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Round off 684,529 to the nearest thousand.\",\n        \"key_fact\": \"685,000\",\n        \"explanation\": \"The hundreds digit is 5, so round up the thousands digit from 4 to 5: 685,000.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Calculate: 45 + 15 × 4\",\n        \"key_fact\": \"105\",\n        \"explanation\": \"Apply BODMAS: Multiply first (15 × 4 = 60), then add 45 (45 + 60 = 105).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Calculate: (72 - 18) ÷ 6 + 12\",\n        \"key_fact\": \"21\",\n        \"explanation\": \"BODMAS: Brackets first (72 - 18 = 54), divide (54 ÷ 6 = 9), then add (9 + 12 = 21).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Which of the following is a prime number?\",\n        \"key_fact\": \"53\",\n        \"explanation\": \"53 has only two factors: 1 and 53. 49 = 7×7, 51 = 3×17, 57 = 3×19.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(29,'psr_math_fractions_decimals','5-Minute Quick Revision: Fractions, Decimals & Operations','Essential Year 6 Brunei PSR revision flashcards for Fractions, Decimals & Operations. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Simplify 18\\/24 to its lowest terms.\",\n        \"key_fact\": \"3\\/4\",\n        \"explanation\": \"Divide both numerator and denominator by 6: 18÷6=3, 24÷6=4.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Calculate: 2\\/3 + 1\\/4\",\n        \"key_fact\": \"11\\/12\",\n        \"explanation\": \"Common denominator 12: 8\\/12 + 3\\/12 = 11\\/12.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Calculate: 3 1\\/2 - 1 3\\/4\",\n        \"key_fact\": \"1 3\\/4\",\n        \"explanation\": \"3 2\\/4 - 1 3\\/4 = 2 6\\/4 - 1 3\\/4 = 1 3\\/4.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Multiply: 2\\/5 × 15\\/16\",\n        \"key_fact\": \"3\\/8\",\n        \"explanation\": \"(2×15)\\/(5×16) = 30\\/80 = 3\\/8.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Divide: 3\\/4 ÷ 6\",\n        \"key_fact\": \"1\\/8\",\n        \"explanation\": \"3\\/4 × 1\\/6 = 3\\/24 = 1\\/8.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(30,'psr_math_percentages_ratios','5-Minute Quick Revision: Percentages, Ratio & Financial Maths','Essential Year 6 Brunei PSR revision flashcards for Percentages, Ratio & Financial Maths. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Express 35% as a fraction in simplest form.\",\n        \"key_fact\": \"7\\/20\",\n        \"explanation\": \"35\\/100 = 7\\/20 by dividing numerator and denominator by 5.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"What is 20% of 350 BND?\",\n        \"key_fact\": \"70 BND\",\n        \"explanation\": \"20\\/100 × 350 = 1\\/5 × 350 = 70 BND.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"A school bag costs $50. A 15% discount is given. What is the sale price?\",\n        \"key_fact\": \"$42.50\",\n        \"explanation\": \"Discount = 15% of $50 = $7.50. Sale price = $50 - $7.50 = $42.50.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"In a class of 40 students, 24 are girls. What percentage of the class are boys?\",\n        \"key_fact\": \"40%\",\n        \"explanation\": \"Boys = 40 - 24 = 16. Percentage = (16\\/40) × 100% = 40%.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"The ratio of red balls to blue balls is 3 : 5. If there are 15 red balls, how many blue balls are there?\",\n        \"key_fact\": \"25\",\n        \"explanation\": \"3 units = 15 -> 1 unit = 5. Blue balls = 5 × 5 = 25.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(31,'psr_math_measurement_geometry','5-Minute Quick Revision: Measurement, Geometry & Volume','Essential Year 6 Brunei PSR revision flashcards for Measurement, Geometry & Volume. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Convert 4.5 kilometers into meters.\",\n        \"key_fact\": \"4,500 m\",\n        \"explanation\": \"1 km = 1,000 m. 4.5 × 1,000 = 4,500 m.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Find the perimeter of a rectangle with length 14 cm and width 8 cm.\",\n        \"key_fact\": \"44 cm\",\n        \"explanation\": \"Perimeter = 2 × (length + width) = 2 × (14 + 8) = 2 × 22 = 44 cm.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Calculate the area of a right-angled triangle with base 10 cm and height 7 cm.\",\n        \"key_fact\": \"35 cm²\",\n        \"explanation\": \"Area = 1\\/2 × base × height = 1\\/2 × 10 × 7 = 35 cm².\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"A cube has sides of length 5 cm. What is its volume?\",\n        \"key_fact\": \"125 cm³\",\n        \"explanation\": \"Volume of cube = s³ = 5 × 5 × 5 = 125 cm³.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Convert 3,250 milliliters into liters.\",\n        \"key_fact\": \"3.25 L\",\n        \"explanation\": \"1 L = 1,000 ml. 3,250 ÷ 1,000 = 3.25 L.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(32,'psr_math_data_probability','5-Minute Quick Revision: Data Handling, Mean & Probability','Essential Year 6 Brunei PSR revision flashcards for Data Handling, Mean & Probability. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Find the mean (average) of these numbers: 12, 16, 20, 24, 28.\",\n        \"key_fact\": \"20\",\n        \"explanation\": \"Sum = 12+16+20+24+28 = 100. Mean = 100 ÷ 5 = 20.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"The total score of 4 tests is 320. What is the average score per test?\",\n        \"key_fact\": \"80\",\n        \"explanation\": \"Average = Total score ÷ number of tests = 320 ÷ 4 = 80.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"In a bar chart, each grid square represents 5 students. A bar is 6 squares tall. How many students does it represent?\",\n        \"key_fact\": \"30\",\n        \"explanation\": \"6 squares × 5 students per square = 30 students.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"What is the median of the following set: 3, 7, 8, 12, 15?\",\n        \"key_fact\": \"8\",\n        \"explanation\": \"The numbers are in order; the middle number is 8.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"In a pictogram, 1 symbol represents 8 books. How many symbols are needed for 48 books?\",\n        \"key_fact\": \"6\",\n        \"explanation\": \"48 ÷ 8 = 6 symbols.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(33,'psr_sci_human_body','5-Minute Quick Revision: Human Body Systems & Health','Essential Year 6 Brunei PSR revision flashcards for Human Body Systems & Health. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Which organ acts as the main muscular pump in the human circulatory system?\",\n        \"key_fact\": \"Heart\",\n        \"explanation\": \"The heart pumps oxygenated and deoxygenated blood throughout the human body.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Which blood vessels carry blood AWAY from the heart under high pressure?\",\n        \"key_fact\": \"Arteries\",\n        \"explanation\": \"Arteries carry oxygen-rich blood away from the heart to body tissues (Remember: A for Away).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Where does gas exchange take place inside the human lungs?\",\n        \"key_fact\": \"Alveoli\",\n        \"explanation\": \"Alveoli are tiny air sacs in the lungs with thin walls where oxygen enters blood and carbon dioxide leaves.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"What gas is absorbed into the blood during inhalation?\",\n        \"key_fact\": \"Oxygen\",\n        \"explanation\": \"During inhalation, fresh oxygen from the air diffuses across the alveoli into the red blood cells.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"What is the main function of red blood cells?\",\n        \"key_fact\": \"Transport oxygen\",\n        \"explanation\": \"Red blood cells contain hemoglobin which binds with oxygen and delivers it to body cells.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(34,'psr_sci_plants_living_things','5-Minute Quick Revision: Plant Processes & Reproduction','Essential Year 6 Brunei PSR revision flashcards for Plant Processes & Reproduction. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"What green pigment in plant leaves absorbs sunlight for photosynthesis?\",\n        \"key_fact\": \"Chlorophyll\",\n        \"explanation\": \"Chlorophyll in chloroplasts traps sunlight energy required to convert CO₂ and water into glucose.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"What are the raw materials required for photosynthesis?\",\n        \"key_fact\": \"Carbon dioxide and water\",\n        \"explanation\": \"Plants take in carbon dioxide from air and water from roots in the presence of sunlight.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"What gas is released by green plants as a byproduct of photosynthesis?\",\n        \"key_fact\": \"Oxygen\",\n        \"explanation\": \"Photosynthesis produces glucose and releases vital oxygen into the atmosphere.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Which plant vascular tissue transports water and minerals upward from roots to leaves?\",\n        \"key_fact\": \"Xylem\",\n        \"explanation\": \"Xylem vessels conduct water and dissolved minerals from roots up the stem to leaves (Remember: Xylem = Water).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Which plant tissue transports manufactured food (sugar) from leaves to all plant parts?\",\n        \"key_fact\": \"Phloem\",\n        \"explanation\": \"Phloem transports glucose\\/sucrose made in leaves to growing shoots and storage roots (Remember: Phloem = Food).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(35,'psr_sci_energy_electricity','5-Minute Quick Revision: Energy, Circuits & Electrical Safety','Essential Year 6 Brunei PSR revision flashcards for Energy, Circuits & Electrical Safety. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"What is the primary source of light and heat energy for planet Earth?\",\n        \"key_fact\": \"The Sun\",\n        \"explanation\": \"Solar energy from the Sun powers the water cycle, weather, and plant photosynthesis on Earth.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Which of the following is a non-renewable source of energy?\",\n        \"key_fact\": \"Petroleum\",\n        \"explanation\": \"Fossil fuels (petroleum, coal, natural gas) take millions of years to form and will eventually deplete.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"What energy transformation occurs when an electric iron is switched on?\",\n        \"key_fact\": \"Electrical energy to Heat energy\",\n        \"explanation\": \"Electrical current heating the heating element converts electrical energy into thermal heat energy.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"In a torchlight, what energy change takes place when it is turned on?\",\n        \"key_fact\": \"Chemical -> Electrical -> Light + Heat\",\n        \"explanation\": \"Chemical energy in dry cells converts into electrical current, then into light and heat in the bulb filament.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"What component in an electrical circuit opens or closes the pathway for current flow?\",\n        \"key_fact\": \"Switch\",\n        \"explanation\": \"A switch allows current to flow when closed and interrupts current flow when opened.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(36,'psr_sci_forces_machines','5-Minute Quick Revision: Forces, Friction & Simple Machines','Essential Year 6 Brunei PSR revision flashcards for Forces, Friction & Simple Machines. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"What is a force?\",\n        \"key_fact\": \"A push or a pull acting on an object\",\n        \"explanation\": \"A force is defined as a push or a pull that can change an object\'s speed, direction, or shape.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"What force pulls all dropped objects downward toward the center of the Earth?\",\n        \"key_fact\": \"Gravity\",\n        \"explanation\": \"Gravitational force pulls objects with mass towards Earth\'s center.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"What force opposes the sliding motion between two surfaces in contact?\",\n        \"key_fact\": \"Friction\",\n        \"explanation\": \"Friction acts in the direction opposite to motion, slowing down moving surfaces.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Which of the following helps to reduce friction between moving machine parts?\",\n        \"key_fact\": \"Applying lubricating oil or grease\",\n        \"explanation\": \"Lubricants form a smooth liquid film that prevents rough surface peaks from grinding together.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Why do racing car tyres have deep tread patterns on wet tracks?\",\n        \"key_fact\": \"To channel water away and increase grip\",\n        \"explanation\": \"Tread grooves expel rainwater, preventing hydroplaning and maintaining road contact.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(37,'psr_sci_matter_earth','5-Minute Quick Revision: States of Matter & The Solar System','Essential Year 6 Brunei PSR revision flashcards for States of Matter & The Solar System. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Which state of matter has a definite shape and a definite volume?\",\n        \"key_fact\": \"Solid\",\n        \"explanation\": \"Solids have tightly packed particles vibrating in fixed positions, maintaining constant shape and volume.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Which state of matter has a definite volume but takes the shape of its container?\",\n        \"key_fact\": \"Liquid\",\n        \"explanation\": \"Liquids flow to match container shape because particles can slide over one another.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"What is the process of a liquid turning into a gas at its boiling point throughout the liquid called?\",\n        \"key_fact\": \"Boiling\",\n        \"explanation\": \"Boiling occurs at a fixed temperature (100°C for pure water) with bubbles forming throughout.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"What is the change of state from gas to liquid called?\",\n        \"key_fact\": \"Condensation\",\n        \"explanation\": \"Condensation occurs when warm gas cools, losing kinetic energy and becoming liquid droplets.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"At what temperature does pure water freeze into ice under normal atmospheric pressure?\",\n        \"key_fact\": \"0°C\",\n        \"explanation\": \"The freezing\\/melting point of pure water is 0°C; its boiling point is 100°C.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(38,'psr_eng_grammar_tenses','5-Minute Quick Revision: Grammar Tenses & Subject-Verb Agreement','Essential Year 6 Brunei PSR revision flashcards for Grammar Tenses & Subject-Verb Agreement. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Neither the teacher nor the students _______ present at the hall yesterday.\",\n        \"key_fact\": \"were\",\n        \"explanation\": \"In \'neither... nor\', the verb agrees with the nearer subject (\'students\' is plural -> were).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"The flock of migratory birds _______ flying south for the winter.\",\n        \"key_fact\": \"is\",\n        \"explanation\": \"Collective nouns like \'flock\' take a singular verb when acting as a single unit.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"She _______ her homework before her mother arrived home from work.\",\n        \"key_fact\": \"had finished\",\n        \"explanation\": \"Past Perfect tense (\'had finished\') indicates an action completed before another past event (\'arrived\').\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Neither of the two books _______ available in the national library.\",\n        \"key_fact\": \"is\",\n        \"explanation\": \"\'Neither of\' takes a singular verb: \'Neither of the two books is available\'.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"By the time we reach Bandar Seri Begawan tomorrow, the ceremony _______.\",\n        \"key_fact\": \"will have started\",\n        \"explanation\": \"Future Perfect tense (\'will have started\') expresses an action completed before a future time.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(39,'psr_eng_parts_of_speech','5-Minute Quick Revision: Prepositions, Conjunctions & Relative Clauses','Essential Year 6 Brunei PSR revision flashcards for Prepositions, Conjunctions & Relative Clauses. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"The adventurous boys jumped _______ the river to cool off on a hot afternoon.\",\n        \"key_fact\": \"into\",\n        \"explanation\": \"\'Into\' indicates movement from outside to inside a body of water.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"The Independence Day celebration will commence _______ 8:00 a.m. sharp.\",\n        \"key_fact\": \"at\",\n        \"explanation\": \"Use \'at\' for specific clock times (\'at 8:00 a.m.\').\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Brunei National Day is proudly celebrated _______ the 23rd of February every year.\",\n        \"key_fact\": \"on\",\n        \"explanation\": \"Use \'on\' for specific calendar dates and days (\'on the 23rd of February\').\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"The girl _______ won the national public speaking competition is my classmate.\",\n        \"key_fact\": \"who\",\n        \"explanation\": \"\'Who\' is the subject relative pronoun referring to people (\'The girl who won\').\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"The historic book _______ cover was torn has been carefully repaired by the librarian.\",\n        \"key_fact\": \"whose\",\n        \"explanation\": \"\'Whose\' shows possession for both people and things (\'whose cover\').\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(40,'psr_eng_vocabulary_idioms','5-Minute Quick Revision: Idioms, Phrasal Verbs & Vocabulary','Essential Year 6 Brunei PSR revision flashcards for Idioms, Phrasal Verbs & Vocabulary. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"What does the idiom \'a piece of cake\' mean?\",\n        \"key_fact\": \"Very easy to accomplish\",\n        \"explanation\": \"\'A piece of cake\' is an English idiom meaning something extremely simple or effortless.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"When someone says they are \'feeling under the weather\', they mean they are:\",\n        \"key_fact\": \"Feeling slightly ill or sick\",\n        \"explanation\": \"\'Under the weather\' means unwell or unwell in health.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"What is the meaning of the phrasal verb \'give up\'?\",\n        \"key_fact\": \"Stop trying or surrender\",\n        \"explanation\": \"\'Give up\' means to cease an effort or abandon hope.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Choose the word that is opposite in meaning (antonym) to \'GENEROUS\':\",\n        \"key_fact\": \"Stingy\",\n        \"explanation\": \"\'Generous\' means willing to give freely; its antonym is \'stingy\' or \'miserly\'.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Choose the word closest in meaning (synonym) to \'HAZARDOUS\':\",\n        \"key_fact\": \"Dangerous\",\n        \"explanation\": \"\'Hazardous\' describes something perilous or dangerous.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(41,'psr_eng_sentence_structures','5-Minute Quick Revision: Active/Passive Voice & Reported Speech','Essential Year 6 Brunei PSR revision flashcards for Active/Passive Voice & Reported Speech. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Change to passive voice: \'The mechanic repaired the damaged car.\'\",\n        \"key_fact\": \"The damaged car was repaired by the mechanic.\",\n        \"explanation\": \"Simple past active (\'repaired\') becomes past passive (\'was repaired by\').\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Change to passive voice: \'The chef is preparing a delicious dessert.\'\",\n        \"key_fact\": \"A delicious dessert is being prepared by the chef.\",\n        \"explanation\": \"Present continuous active (\'is preparing\') becomes \'is being prepared\'.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Convert to indirect speech: \'I am reading an adventure novel,\' said Danial.\",\n        \"key_fact\": \"Danial said that he was reading an adventure novel.\",\n        \"explanation\": \"Direct \'I am reading\' shifts back in tense to \'he was reading\' in reported speech.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Convert to indirect speech: \'Where do you live?\' asked the police officer.\",\n        \"key_fact\": \"The police officer asked where I lived.\",\n        \"explanation\": \"In reported questions, do-support drops and word order becomes subject + verb: \'where I lived\'.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Combine using \'Although\': \'It was raining heavily. The boys continued playing football.\'\",\n        \"key_fact\": \"Although it was raining heavily, the boys continued playing football.\",\n        \"explanation\": \"\'Although\' shows concession at the beginning of the dependent contrast clause.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(42,'psr_bm_tatabahasa_imbuhan','5-Minute Quick Revision: Morfologi, Golongan Kata & Imbuhan','Essential Year 6 Brunei PSR revision flashcards for Morfologi, Golongan Kata & Imbuhan. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Pilih ayat yang mengandungi Kata Kerja Transitif:\",\n        \"key_fact\": \"Petani itu menanam padi di sawah.\",\n        \"explanation\": \"Kata kerja transitif (menanam) memerlukan objek (padi) selepasnya.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Imbuhan apitan \'ke-...-an\' dalam perkataan \'kejayaan\' membawa maksud:\",\n        \"key_fact\": \"Hal atau keadaan\",\n        \"explanation\": \"Apitan \'ke-...-an\' pada kata dasar \'jaya\' membentuk kata nama abstrak yang bermaksud hal atau keadaan berjaya.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Kanak-kanak itu menangis kerana kakinya _______ duri pokok semalu.\",\n        \"key_fact\": \"tercucuk\",\n        \"explanation\": \"Imbuhan awalan \'ter-\' menunjukkan perbuatan yang tidak disengajakan (tercucuk duri).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Pilih kata ganda semu yang betul:\",\n        \"key_fact\": \"Kura-kura\",\n        \"explanation\": \"Kata ganda semu ialah kata yang bentuk dasarnya tidak mempunyai makna jika tidak digandakan (kura-kura, rama-rama, agar-agar).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Encik Rashid _______ jawatan sebagai pengurus cawangan bank tersebut.\",\n        \"key_fact\": \"menyandang\",\n        \"explanation\": \"Ejaan betul dengan imbuhan \'meN-\' pada kata dasar \'sandang\' ialah \'menyandang\'.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(43,'psr_bm_penjodoh_bilangan','5-Minute Quick Revision: Penjodoh Bilangan Komprehensif','Essential Year 6 Brunei PSR revision flashcards for Penjodoh Bilangan Komprehensif. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Pak Salleh menyabit rumput menggunakan se_______ sabit yang tajam.\",\n        \"key_fact\": \"bilah\",\n        \"explanation\": \"Penjodoh bilangan \'bilah\' digunakan untuk benda tajam dan runcing seperti parang, pisau, sabit, dan pedang.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Polis merampas dua _______ senapang patah daripada pemburu haram itu.\",\n        \"key_fact\": \"laras\",\n        \"explanation\": \"\'Laras\' digunakan khas untuk senjata api seperti senapang dan meriam.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Posmen menyerahkan se_______ surat penting kepada penghulu kampung.\",\n        \"key_fact\": \"pucuk\",\n        \"explanation\": \"\'Pucuk\' digunakan untuk surat dan senjata api kecil seperti pistol dan jarum.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Puan Maryam membeli se_______ rantai emas yang cantik di kedai emas itu.\",\n        \"key_fact\": \"utas\",\n        \"explanation\": \"\'Utas\' digunakan untuk benda panjang dan berurai seperti rantai, tali, dan dawai.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Tiga _______ meriam lama masih terpelihara rapi di Muzium Brunei.\",\n        \"key_fact\": \"pucuk\",\n        \"explanation\": \"\'Laras\' atau \'pucuk\' untuk meriam; \'laras\' digunakan khusus untuk senjata api berlaras.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(44,'psr_bm_peribahasa','5-Minute Quick Revision: Peribahasa, Simpulan Bahasa & Kiasan','Essential Year 6 Brunei PSR revision flashcards for Peribahasa, Simpulan Bahasa & Kiasan. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Orang yang rajin dan tidak pernah mengenal penat lelah digelar:\",\n        \"key_fact\": \"Ringan tulang\",\n        \"explanation\": \"Ringan tulang bermaksud orang yang rajin bekerja. Lawannya berat tulang (pemalas).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Peribahasa \'Bagai aur dengan tebing\' menggambarkan:\",\n        \"key_fact\": \"Masyarakat yang sentiasa tolong-menolong dan bersatu padu\",\n        \"explanation\": \"Aur dan tebing saling menyokong antara satu sama lain untuk mengelakkan tebing runtuh.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Maksud simpulan bahasa \'makan suap\' ialah:\",\n        \"key_fact\": \"Menerima rasuah\",\n        \"explanation\": \"Makan suap bermaksud menerima sogokan atau wang rasuah secara haram.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Peribahasa \'Ada udang di sebalik batu\' membawa pengertian:\",\n        \"key_fact\": \"Melakukan sesuatu dengan niat tersembunyi\",\n        \"explanation\": \"Ada muslihat atau motif terselindung di sebalik kebaikan yang ditunjukkan.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Orang yang sombong dan enggan mendengar teguran orang lain digelar:\",\n        \"key_fact\": \"Besar kepala\",\n        \"explanation\": \"Besar kepala bermaksud bongkak, sombong dan megah diri.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(45,'psr_bm_kosa_kata_pemahaman','5-Minute Quick Revision: Sinonim, Antonim & Kosa Kata Kontekstual','Essential Year 6 Brunei PSR revision flashcards for Sinonim, Antonim & Kosa Kata Kontekstual. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Pilih perkataan seerti (sinonim) bagi \'CEKAL\':\",\n        \"key_fact\": \"Tabah\",\n        \"explanation\": \"Cekal bermaksud tabah, kuat semangat dan tidak mudah putus asa.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Pilih perkataan berlawan (antonim) bagi \'TULUS\':\",\n        \"key_fact\": \"Khianat\",\n        \"explanation\": \"Tulus bermaksud jujur dan ikhlas; lawannya khianat atau berpura-pura.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Apakah maksud perkataan \'prihatin\' dalam ayat: \'Kerajaan amat prihatin terhadap kebajikan rakyat.\'?\",\n        \"key_fact\": \"Mengambil berat dan peka\",\n        \"explanation\": \"Prihatin bermaksud mengambil berat, peka dan menunjukkan kepedulian yang mendalam.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Pilih sinonim bagi perkataan \'MUTLAK\':\",\n        \"key_fact\": \"Penuh \\/ Mutlak\",\n        \"explanation\": \"Kuasa mutlak bermaksud kuasa penuh yang tidak terhad oleh pihak lain.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Pilih antonim bagi \'SUBUR\':\",\n        \"key_fact\": \"Gersang\",\n        \"explanation\": \"Tanah subur mudah ditumbuhi tanaman; tanah gersang kering-kontang dan tandus.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(46,'psr_mib_falsafah_konsep','5-Minute Quick Revision: Falsafah Negara & Konsep Teras MIB','Essential Year 6 Brunei PSR revision flashcards for Falsafah Negara & Konsep Teras MIB. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Apakah maksud singkatan MIB dalam konteks Negara Brunei Darussalam?\",\n        \"key_fact\": \"Melayu Islam Beraja\",\n        \"explanation\": \"MIB ialah falsafah kebangsaan Negara Brunei Darussalam yang bermaksud Melayu Islam Beraja.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Bilakah Falsafah Melayu Islam Beraja (MIB) dimasyhurkan secara rasmi?\",\n        \"key_fact\": \"Semasa Pemasyhuran Kemerdekaan pada 1 Januari 1984\",\n        \"explanation\": \"Kebawah Duli Yang Maha Mulia memasyhurkan Brunei sebagai sebuah negara Melayu Islam Beraja pada 1 Januari 1984.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Siapakah yang memegang tampuk pemerintahan tertinggi dan ketua agama Islam di Brunei Darussalam?\",\n        \"key_fact\": \"Kebawah Duli Yang Maha Mulia Paduka Seri Baginda Sultan\",\n        \"explanation\": \"Sultan ialah Ketua Negara, Ketua Kerajaan, dan Ketua Agama Islam di Negara Brunei Darussalam.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Apakah pegangan mazhab fiqh rasmi bagi Negara Brunei Darussalam?\",\n        \"key_fact\": \"Mazhab Syafi\'i\",\n        \"explanation\": \"Brunei Darussalam berpegang teguh kepada Ahli Sunnah Waljamaah mengikut Mazhab Syafi\'i.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Unsur \'Melayu\' dalam MIB merujuk kepada:\",\n        \"key_fact\": \"Kebudayaan, tatasusila, dan adat istiadat bangsa Melayu Brunei\",\n        \"explanation\": \"Unsur Melayu memelihara nilai-nilai murni, adat istiadat, dan bahasa Melayu sebagai bahasa rasmi.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(47,'psr_mib_sejarah_kesultanan','5-Minute Quick Revision: Sejarah Kesultanan Brunei & Mercu Tanda','Essential Year 6 Brunei PSR revision flashcards for Sejarah Kesultanan Brunei & Mercu Tanda. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Siapakah Sultan Brunei yang pertama memeluk agama Islam?\",\n        \"key_fact\": \"Sultan Muhammad Shah (Awang Alak Betatar)\",\n        \"explanation\": \"Awang Alak Betatar memeluk Islam dan memakai gelaran Sultan Muhammad Shah (1363-1402).\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Sultan Brunei manakah yang berasal dari keturunan Rasulullah SAW (Ahlul Bait) dan dikenali sebagai \'Sultan Berkat\'?\",\n        \"key_fact\": \"Sultan Sharif Ali\",\n        \"explanation\": \"Sultan Sharif Ali (Sultan ke-3) berasal dari Taif dan digelar Sultan Berkat kerana memajukan syiar Islam dan membina masjid pertama.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Sultan manakah yang terkenal sebagai \'Nakhoda Ragam\' dan membawa zaman kegemilangan empayar Brunei?\",\n        \"key_fact\": \"Sultan Bolkiah\",\n        \"explanation\": \"Sultan Bolkiah (Sultan ke-5) mengemudi empayar maritim Brunei meliputi seluruh Borneo dan Kepulauan Sulu hingga Manila.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Apakah peristiwa bersejarah yang berlaku pada tahun 1578 antara Brunei dan pihak Sepanyol?\",\n        \"key_fact\": \"Perang Kastila\",\n        \"explanation\": \"Perang Kastila berlaku apabila angkatan Sepanyol cuba menakluki Brunei tetapi berjaya diundurkan oleh pahlawan Brunei di bawah pimpinan Bendahara Sakam.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Siapakah pahlawan gagah berani Brunei yang mengetuai perjuangan mengusir tentera Sepanyol dalam Perang Kastila?\",\n        \"key_fact\": \"Pengiran Bendahara Sakam\",\n        \"explanation\": \"Bendahara Sakam bersama hulubalang dan pahlawan rakyat bangkit mengusir penjajah Sepanyol dari Kota Batu.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]'),(48,'psr_mib_adat_tatasusila','5-Minute Quick Revision: Adat Istiadat, Tatasusila & Budaya Brunei','Essential Year 6 Brunei PSR revision flashcards for Adat Istiadat, Tatasusila & Budaya Brunei. Review core concepts, formulas, and key examination facts.','[\n    {\n        \"card_number\": 1,\n        \"title\": \"PSR Key Concept 1\",\n        \"question\": \"Apakah cara bersalaman yang sopan dan beradab dalam tatasusila masyarakat Melayu Brunei?\",\n        \"key_fact\": \"Bersalaman dengan kedua-dua belah tangan lalu meletakkannya di dada\",\n        \"explanation\": \"Bersalaman dua tangan dan merapatkan ke dada menunjukkan rasa ikhlas dan hormat mendalam.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 2,\n        \"title\": \"PSR Key Concept 2\",\n        \"question\": \"Bagaimanakah cara yang betul untuk menunjukkan arah sesuatu benda kepada orang tua?\",\n        \"key_fact\": \"Menggunakan ibu jari tangan kanan yang digenggam dengan sopan\",\n        \"explanation\": \"Dalam tatasusila Melayu Brunei, menunjuk dengan jari telunjuk dianggap kurang sopan; gunakan ibu jari kanan.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 3,\n        \"title\": \"PSR Key Concept 3\",\n        \"question\": \"Apabila berjalan melintas di hadapan orang yang lebih tua, kita hendaklah:\",\n        \"key_fact\": \"Menundukkan sedikit badan sambil menghulurkan tangan ke bawah sambil meminta lalu\",\n        \"explanation\": \"Menundukkan badan dan mengucap \'minta lalu\' menunjukkan adab merendah diri.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 4,\n        \"title\": \"PSR Key Concept 4\",\n        \"question\": \"Apakah makanan tradisi Brunei yang diperbuat daripada sagu rumbia dan dimakan dengan cecah cacah?\",\n        \"key_fact\": \"Ambuyat\",\n        \"explanation\": \"Ambuyat diperbuat daripada ambulung (sagu rumbia) dan dimakan menggunakan candas bersama kuah binjai atau tempoyak.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    },\n    {\n        \"card_number\": 5,\n        \"title\": \"PSR Key Concept 5\",\n        \"question\": \"Alat khas yang diperbuat daripada buluh menyerupai penyepit untuk memakan ambuyat dipanggil:\",\n        \"key_fact\": \"Candas\",\n        \"explanation\": \"Candas ialah penyepit buluh tradisional untuk menggulung ambuyat.\",\n        \"quick_tip\": \"Tip: Master the underlying rule or formula to answer related PSR questions with speed and precision.\"\n    }\n]');
