INSERT INTO `subjects` VALUES ('bahasa_melayu','Bahasa Melayu','Bahasa Melayu','Suku kata, kenderaan, haiwan, bulan & tatabahasa asas.','📚','from-emerald-400 to-teal-600','#10B981',1,'Kindergarten 3 (KG3)'),('english','English','English Language','Phonics, pronouns, articles, demonstratives & reading comprehension.','🔤','from-sky-400 to-blue-600','#0EA5E9',3,'Kindergarten 3 (KG3)'),('ict','ICT & Computer','Computer Technology','Computer parts, storage drives, peripheral spelling & Input/Output.','💻','from-rose-400 to-pink-600','#EC4899',5,'Kindergarten 3 (KG3)'),('maths','Mathematics','Mathematics','Analog clocks & time, descending numbers, addition & subtraction.','🔢','from-amber-400 to-orange-500','#F59E0B',2,'Kindergarten 3 (KG3)'),('psr_bahasa_melayu','Bahasa Melayu (PSR)','Bahasa Melayu PSR (Tahun 6)','Tatabahasa, imbuhan awalan/akhiran/apitan, penjodoh bilangan, peribahasa Brunei & kosa kata.','🇧🇳','from-amber-500 to-red-600','#D97706',14,'Year 6 (PSR)'),('psr_english','English Language (PSR)','English Language (Year 6)','Tenses, subject-verb agreement, prepositions, idioms, phrasal verbs, voice & sentence structures.','📖','from-purple-600 to-pink-700','#9333EA',13,'Year 6 (PSR)'),('psr_maths','Mathematics (PSR)','Matematik PSR (Tahun 6)','Numbers & operations, fractions, decimals, percentages, measurement, area, volume & data handling.','📐','from-blue-600 to-indigo-700','#2563EB',11,'Year 6 (PSR)'),('psr_mib','Melayu Islam Beraja (MIB)','Melayu Islam Beraja (Tahun 6)','Konsep MIB, sejarah Kesultanan Brunei, Sultan berdaulat, tatasusila, adat istiadat & kebudayaan.','🕌','from-yellow-500 to-amber-700','#B45309',15,'Year 6 (PSR)'),('psr_science','Science (PSR)','Sains PSR (Tahun 6)','Human body systems, plant processes, energy, circuits, forces, machines, matter & solar system.','🔬','from-emerald-500 to-teal-700','#059669',12,'Year 6 (PSR)'),('science','Science','Early Science','Animal habitats, sink or float, materials, astronomy & plants.','🔬','from-purple-400 to-indigo-600','#8B5CF6',4,'Kindergarten 3 (KG3)');
/*!40000 ALTER TABLE `subjects` ENABLE KEYS */;
