INSERT INTO `topics` VALUES ('bm_binatang','bahasa_melayu','Haiwan 2 Kaki & 4 Kaki','Haiwan Berkaki 2 dan Berkaki 4','Mengelaskan pelbagai haiwan mengikut bilangan kakinya.','🐾','bg-green-100 text-green-800',300,4,'Kindergarten 3 (KG3)'),('bm_bulan','bahasa_melayu','12 Bulan dalam Setahun','12 Bulan dalam Setahun','Mengecam dan menyusun nama 12 bulan mengikut turutan yang betul.','📅','bg-emerald-100 text-emerald-800',300,1,'Kindergarten 3 (KG3)'),('bm_ini_itu','bahasa_melayu','Kata Tunjuk: Ini & Itu','Penggunaan Kata Tunjuk Ini dan Itu','Memahami perbezaan jarak dekat (Ini) dan jarak jauh (Itu).','👉','bg-lime-100 text-lime-800',300,5,'Kindergarten 3 (KG3)'),('bm_kenderaan','bahasa_melayu','Kenderaan Darat, Air & Udara','Kenderaan Darat, Air dan Udara','Kenal pasti jenis kenderaan dan laluan pergerakannya.','🚗','bg-cyan-100 text-cyan-800',300,3,'Kindergarten 3 (KG3)'),('bm_suku_kata','bahasa_melayu','Pecahkan Suku Kata','Pecahkan Perkataan kepada Suku Kata','Membina perkataan mudah melalui cantuman dua suku kata terbuka.','🧩','bg-teal-100 text-teal-800',300,2,'Kindergarten 3 (KG3)'),('eng_articles','english','Articles: A and An','Articles A or An','Use \"an\" before vowel sounds (a, e, i, o, u) and \"a\" before consonants.','🔤','bg-violet-100 text-violet-800',300,4,'Kindergarten 3 (KG3)'),('eng_blending','english','Beginning Blends (ch- & th-)','Beginning Blending Sound Box','Recognise and match beginning blend sounds: ch- (chair) and th- (thorn).','🗣️','bg-blue-100 text-blue-800',300,2,'Kindergarten 3 (KG3)'),('eng_comprehension','english','Reading Comprehension','Short Stories: Troy & Andy','Read sweet passages, understand context, and answer smart questions.','📖','bg-sky-100 text-sky-800',300,7,'Kindergarten 3 (KG3)'),('eng_days_months','english','Days of Week & Months','Days of the Week and Month Numbers','Learn the 7 days of the week in sequence and match months to their numbers.','🗓️','bg-sky-100 text-sky-800',300,1,'Kindergarten 3 (KG3)'),('eng_demonstratives','english','This, That, These, Those','Demonstrative Pronouns','Master near vs far, singular vs plural pointer words.','👉','bg-purple-100 text-purple-800',300,6,'Kindergarten 3 (KG3)'),('eng_has_have','english','Using Has and Have','Has vs Have Rules','He/She/It uses \"has\", while I/We/They uses \"have\".','🤲','bg-fuchsia-100 text-fuchsia-800',300,5,'Kindergarten 3 (KG3)'),('eng_pronouns','english','Pronouns (He, She, It, They)','Personal Pronouns','Choose the correct pronoun for boys, girls, objects, and groups.','👥','bg-indigo-100 text-indigo-800',300,3,'Kindergarten 3 (KG3)'),('ict_counting','ict','Count Computer Peripherals','Count Computer Peripherals','Count and determine the correct number of computer devices.','🔢','bg-indigo-100 text-indigo-800',300,3,'Kindergarten 3 (KG3)'),('ict_input_output','ict','Input (I) vs Output (O) Devices','Input vs Output Devices','Recognise whether a device feeds data in (Input) or presents results (Output).','🔌','bg-blue-100 text-blue-800',300,5,'Kindergarten 3 (KG3)'),('ict_parts','ict','All About Computer Parts','All About Computer Peripherals','Identify monitors, keyboards, printers, headphones, scanners, and system units.','🖥️','bg-pink-100 text-pink-800',300,2,'Kindergarten 3 (KG3)'),('ict_spelling','ict','Fill in the Missing Letters','Fill in the Missing Letters','Complete the missing letters for computer peripheral names.','🔤','bg-purple-100 text-purple-800',300,4,'Kindergarten 3 (KG3)'),('ict_storage','ict','Computer Drives & Storage','Computer Drives and Storage','Learn about Hard disk drives, floppy disks, CD-ROMs, memory cards, and USB pendrives.','💾','bg-rose-100 text-rose-800',300,1,'Kindergarten 3 (KG3)'),('math_addition','maths','Addition (Combining Numbers)','Basic Addition with Pictures','Count and add groups of fun objects together.','➕','bg-yellow-100 text-yellow-800',300,3,'Kindergarten 3 (KG3)'),('math_clocks','maths','Analog Clocks & Time','Reading Clock Numbers & Hands','Learn the hour hand, minute hand, and how to read the clock.','🕒','bg-amber-100 text-amber-800',300,1,'Kindergarten 3 (KG3)'),('math_descending','maths','Descending Numbers (20 to 1)','Descending Numbers 20 to 1','Count numbers from largest to smallest, from 20 down to 1.','📉','bg-orange-100 text-orange-800',300,2,'Kindergarten 3 (KG3)'),('math_subtraction','maths','Subtraction (Taking Away)','Basic Subtraction with Pictures','Count what remains when items are removed or popped.','➖','bg-red-100 text-red-800',300,4,'Kindergarten 3 (KG3)'),('psr_bm_kosa_kata_pemahaman','psr_bahasa_melayu','Sinonim, Antonim & Kosa Kata Kontekstual','Kosa Kata & Pemahaman Teks','Perkataan seerti (sinonim), berlawan (antonim), kata ganda, bahasa kiasan dan pemahaman petikan peperiksaan PSR.','📖','bg-orange-100 text-orange-800',300,4,'Year 6 (PSR)'),('psr_bm_penjodoh_bilangan','psr_bahasa_melayu','Penjodoh Bilangan Komprehensif','Penjodoh Bilangan Peperiksaan PSR','Penggunaan jitu penjodoh bilangan: laras, pucuk, bilah, bentuk, kaki, lembar, naskhah, rumpun, utas dan ulas.','🔢','bg-teal-100 text-teal-800',300,2,'Year 6 (PSR)'),('psr_bm_peribahasa','psr_bahasa_melayu','Peribahasa, Simpulan Bahasa & Kiasan','Peribahasa & Simpulan Bahasa Melayu','Maksud dan penggunaan simpulan bahasa, perumpamaan, pepatah, dan bidalan warisan Melayu serta kiasan Brunei.','💎','bg-red-100 text-red-800',300,3,'Year 6 (PSR)'),('psr_bm_tatabahasa_imbuhan','psr_bahasa_melayu','Morfologi, Golongan Kata & Imbuhan','Morfologi & Imbuhan Lengkap','Kata Nama, Kata Kerja transitif/tak transitif, Kata Adjektif, Kata Hubung, Kata Pemeri dan imbuhan apitan/sisipan.','📚','bg-amber-100 text-amber-800',300,1,'Year 6 (PSR)'),('psr_eng_grammar_tenses','psr_english','Grammar Tenses & Subject-Verb Agreement','Tenses & Subject-Verb Concord','Past perfect, present perfect, continuous tenses, modal verbs, collective nouns and subject-verb agreement rules.','⏱️','bg-purple-100 text-purple-800',300,1,'Year 6 (PSR)'),('psr_eng_parts_of_speech','psr_english','Prepositions, Conjunctions & Relative Clauses','Parts of Speech & Connectors','Prepositions of time and movement, correlative conjunctions (neither/nor), relative pronouns (who/whom/whose) and adverbs.','🔗','bg-indigo-100 text-indigo-800',300,2,'Year 6 (PSR)'),('psr_eng_sentence_structures','psr_english','Active/Passive Voice & Reported Speech','Sentence Transformation','Converting active to passive voice, direct to indirect speech, question tags and complex sentence synthesis.','📝','bg-pink-100 text-pink-800',300,4,'Year 6 (PSR)'),('psr_eng_vocabulary_idioms','psr_english','Idioms, Phrasal Verbs & Vocabulary','Idiomatic Expressions & Lexis','PSR exam idioms, phrasal verbs, context clues, advanced synonyms and antonyms.','💡','bg-amber-100 text-amber-800',300,3,'Year 6 (PSR)'),('psr_math_data_probability','psr_maths','Data Handling, Mean & Probability','Pengendalian Data & Purata','Calculating the mean (average), median, mode, range, interpreting bar charts, pie charts and simple probability.','📊','bg-purple-100 text-purple-800',300,5,'Year 6 (PSR)'),('psr_math_fractions_decimals','psr_maths','Fractions, Decimals & Operations','Pecahan & Perpuluhan','Addition, subtraction, multiplication and division of proper, improper and mixed fractions, plus decimal conversions.','🍰','bg-indigo-100 text-indigo-800',300,2,'Year 6 (PSR)'),('psr_math_measurement_geometry','psr_maths','Measurement, Geometry & Volume','Ukuran, Geometri & Isi Padu','Metric unit conversions, 24-hour time, perimeter, area of 2D shapes, angles and volume of cuboids.','📐','bg-cyan-100 text-cyan-800',300,4,'Year 6 (PSR)'),('psr_math_numbers','psr_maths','Numbers, Place Value & BODMAS','Nombor Bulat & Operasi Bergabung','Whole numbers up to 1,000,000, place value, prime numbers, rounding off and order of operations (BODMAS).','🔢','bg-blue-100 text-blue-800',300,1,'Year 6 (PSR)'),('psr_math_percentages_ratios','psr_maths','Percentages, Ratio & Financial Maths','Peratusan, Nisbah & Wang','Calculate percentages of quantities, discounts, profit/loss, simple interest, currency and ratio sharing.','💰','bg-emerald-100 text-emerald-800',300,3,'Year 6 (PSR)'),('psr_mib_adat_tatasusila','psr_mib','Adat Istiadat, Tatasusila & Budaya Brunei','Adat Istiadat & Tatasusila Brunei','Tatasusila bersalaman, bahasa dalam (istana), makanan tradisi (ambuyat, kelupis), tenunan Brunei dan adab berteraskan syarak.','🤝','bg-emerald-100 text-emerald-800',300,3,'Year 6 (PSR)'),('psr_mib_falsafah_konsep','psr_mib','Falsafah Negara & Konsep Teras MIB','Falsafah Negara Melayu Islam Beraja','Maksud Melayu, Islam, dan Beraja, Perlembagaan 1959, Pemasyhuran 1984, Negara Zikir, Jata Kebangsaan dan Wawasan 2035.','👑','bg-yellow-100 text-yellow-800',300,1,'Year 6 (PSR)'),('psr_mib_sejarah_kesultanan','psr_mib','Sejarah Kesultanan Brunei & Mercu Tanda','Sejarah Kesultanan Melayu Brunei','Sultan Muhammad Shah, Sultan Sharif Ali, Sultan Bolkiah, Perang Kastila, Arkitek Brunei Moden dan mercu tanda negara.','🏛️','bg-amber-100 text-amber-800',300,2,'Year 6 (PSR)'),('psr_sci_energy_electricity','psr_science','Energy, Circuits & Electrical Safety','Tenaga, Litar Elektrik & Keselamatan','Forms of energy, renewable vs non-renewable sources, series vs parallel circuits, conductors, insulators and fuses.','⚡','bg-yellow-100 text-yellow-800',300,3,'Year 6 (PSR)'),('psr_sci_forces_machines','psr_science','Forces, Friction & Simple Machines','Daya, Geseran & Mesin Ringkas','Gravity, friction, air resistance, balanced forces, levers (Class 1, 2, 3), pulleys, ramps and wheel & axle.','⚙️','bg-stone-100 text-stone-800',300,4,'Year 6 (PSR)'),('psr_sci_human_body','psr_science','Human Body Systems & Health','Sistem Tubuh Manusia & Kesihatan','Circulatory system, heart & blood vessels, respiratory system, lungs & alveoli, digestion and skeletal framework.','🫀','bg-red-100 text-red-800',300,1,'Year 6 (PSR)'),('psr_sci_matter_earth','psr_science','States of Matter & The Solar System','Jirim, Kitaran Air & Sistem Suria','Solids, liquids, gases, evaporation, condensation, water cycle, day/night rotation and solar system planets.','🌍','bg-sky-100 text-sky-800',300,5,'Year 6 (PSR)'),('psr_sci_plants_living_things','psr_science','Plant Processes & Reproduction','Proses Hidup Tumbuhan','Photosynthesis, xylem & phloem transport, pollination, seed dispersal mechanisms and germination requirements.','🌱','bg-green-100 text-green-800',300,2,'Year 6 (PSR)'),('sci_celestial','science','Sun, Moon, Star & Earth','Sun, Moon, Star, and Earth','Learn about the celestial bodies in our sky and our home planet Earth.','🌍','bg-amber-100 text-amber-800',300,3,'Kindergarten 3 (KG3)'),('sci_land_sea','science','Land vs Sea Animals','Land and Sea Animals Habitat','Identify whether animals live on land or in the ocean.','🐬','bg-emerald-100 text-emerald-800',300,1,'Kindergarten 3 (KG3)'),('sci_materials','science','Materials: Metal, Glass & Paper','Objects Made of Metal, Glass & Paper','Identify everyday objects made of metal, transparent glass, or paper.','🪨','bg-stone-100 text-stone-800',300,4,'Kindergarten 3 (KG3)'),('sci_plants','science','Parts & Needs of a Plant','Parts of a Plant & Needs to Grow','Identify roots, stem, leaves, flower, fruit and sunlight, air, water.','🌱','bg-green-100 text-green-800',300,6,'Kindergarten 3 (KG3)'),('sci_pollution','science','Types of Pollution','Types of Pollutions','Learn about air pollution, water/sea pollution, and land pollution.','🏭','bg-red-100 text-red-800',300,5,'Kindergarten 3 (KG3)'),('sci_sink_float','science','Sink or Float','Objects that Sink or Float','Discover which objects sink to the bottom or float on water.','⚓','bg-cyan-100 text-cyan-800',300,2,'Kindergarten 3 (KG3)');
